(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-consistency-models-2023"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-1\">一 · 现场：一条被采样循环锁死的在线队列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-2\">二 · 旧方案的三条路，各自撞在哪堵墙上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-3\">三 · 为什么非改不可：SLO 与容量的算术</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-4\">四 · 论文给出的结构替换：把迭代换成一次映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-5\">五 · 旧方案留下的失败模式，正是新结构的验收清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-6\">六 · 先把“请求”拆成可测的向量，而不是一个 QPS</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-7\">七 · 输入长度分布与条件复杂度决定档位路由</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-8\">八 · 批大小、CFG 合并与显存峰值的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-9\">九 · SLO 分层与长尾：一步档不是万能档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-10\">十 · 负载与方案的相互塑造：可复现的测量清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-11\">十一 · 负载如何反向约束步数档位：一步与多步的边界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-12\">十二 · 一致性函数前向的算子骨架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-13\">十三 · 数据类型：FP16 / BF16 / FP8 / NVFP4 的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-14\">十四 · 累加精度与误差传播</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-15\">十五 · Blackwell 特性：tcgen05、TMEM、2-SM MMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-16\">十六 · 精度方案与步数档位的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-17\">十七 · 数值稳定性的两个具体机制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-18\">十八 · 精度选择的边界：一步档的数值风险与 Blackwell 数据通路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-19\">十九 · 显存账本的三个户头：权重、激活、KV 类中间态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-20\">二十 · 分页与复用：把跨步驻留变成可管理的池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-21\">二十一 · 压缩：精度换容量，但要盯住一步档的质量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-22\">二十二 · 卸载：把冷数据挪出 HBM，代价是带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-23\">二十三 · 带宽瓶颈在哪：HBM3e 容量与流量的分开算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-24\">二十四 · 一个可复算的显存预算：从不等式到调度参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-25\">二十五 · 从“步数档位”到调度原语：为什么扩散服务的批处理不能照搬自回归</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-26\">二十六 · Chunked prefill 在扩散里的对应物：解码分块与网格分段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-27\">二十七 · 优先级与抢占：一步档与多步档的显存争夺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-28\">二十八 · 分离式预填/解码在扩散服务里的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-29\">二十九 · 尾延迟怎么压：批成形的等待策略与回退路由</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-30\">三十 · 并行拓扑：一步档与多步档对切分维度的不同偏好</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-31\">三十一 · NVLink 5 与 NVSwitch：域内通信的带宽账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-32\">三十二 · All-to-All 与 EP：MoE 骨干的通信形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-33\">三十三 · NIXL 传输：分离式部署下的数据面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-34\">三十四 · 通信何时成为瓶颈：三个可操作的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-35\">三十五 · 并行切分下的一致性采样：通信何时吃掉少步收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-36\">三十六 · 精度塌陷：一步档的“看起来对、其实不对”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-37\">三十七 · OOM：中间激活而非 KV 才是主约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-38\">三十八 · 批抖动：步数分档下的吞吐震荡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-39\">三十九 · 尾延迟：回退路径的隐藏成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-40\">四十 · 静默降级：没有报错的质量滑坡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-41\">四十一 · 回滚：按档位而非按整机</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-42\">四十二 · 失败模式与诊断：精度塌陷、OOM、批抖动、尾延迟、静默降级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-43\">四十三 · 基准口径的三层结构：模型态、服务态、硬件态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-44\">四十四 · 批与并发的耦合：一步档与多步档不是同一个容量问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-45\">四十五 · 指标读法：TTFT/TPOT 在扩散服务里的映射与陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-46\">四十六 · 哪些提升不可比：四类常见的伪对比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-47\">四十七 · 可复现的最小报告模板与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-48\">四十八 · 基准口径：步数档位不可混读，显存与延迟要分账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-49\">四十九 · 迁移到非扩散生成范式：一致性约束的前提在不在</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-50\">五十 · 换骨干与换分辨率：f(x,t) 的容量与感受野要重估</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-51\">五十一 · 蒸馏路径的迁移边界：教师精度决定学生上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-52\">五十二 · 规模上限：一步档的吞吐天花板在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-53\">五十三 · 不适用的场景与硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-54\">五十四 · 迁移检查清单：把判断落成可执行项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-consistency-models-2023-sec-55\">五十五 · 迁移边界：一致性蒸馏在哪些骨干、条件形态与规模上会失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:590px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样器从先验噪声分布取初始样本 x_T，并确定离散时间步序列与目标步数。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">一致性函数接收 (x_t,t) 与可选条件嵌入，单次前向直接输出轨迹终…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">若采用多步一致性采样，则在时间网格上交替执行去噪与重新加噪，逐步逼近终…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条件生成时将 CFG 合并为单次批前向或按批拼接，避免双分支显存翻倍。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出终点样本经 VAE 解码为像素或潜空间结果，返回请求队列并记录步数…</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">服务端按步数档位路由：一步档走低延迟队列，多步档走吞吐队列并监控失败率。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-consistency-models-2023-sec-1\">一 · 现场：一条被采样循环锁死的在线队列</h3>\n<p>设想一个已经上线的文生图服务：请求从网关进入队列，调度器按 SLO 把提示词切成批，送进扩散骨干，再经 VAE 解码返回。瓶颈不在骨干的算力峰值，而在采样循环本身——每个请求要沿时间轴反复调用同一个网络几十次，每一步都伴随一次 kernel 启动、一次条件嵌入读取、一次中间激活写回。队列深度一旦上来，单请求延迟与整机吞吐同时被这条循环钉住：批调大能摊薄权重读取，但中间激活随批线性上涨，显存先撞墙；批调小则 kernel 启动开销与条件分支的固定成本占比抬升，吞吐上不去。工程上真正难受的是，这条循环的迭代次数是模型语义的一部分，不是调度器能随意改写的旋钮——降步数就掉质量，保质量就保不住延迟。</p>\n<p>把代价写成式子更清楚。设单步前向的算力开销为 <span class=\"inline-math\">C</span>、单步显存峰值为 <span class=\"inline-math\">M</span>、步数为 <span class=\"inline-math\">N</span>，则单请求延迟近似正比于 <span class=\"inline-math\">N·(C + M/BW)</span>，其中 <span class=\"inline-math\">BW</span> 是有效带宽；批大小为 <span class=\"inline-math\">b</span> 时，激活占用约为 <span class=\"inline-math\">b·M</span>，于是吞吐上限被 <span class=\"inline-math\">min(算力/b·C, 显存/b·M)</span> 夹住。关键在于 <span class=\"inline-math\">N</span> 出现在延迟的乘子里，也在吞吐的分母里：它同时惩罚两端。这就是为什么服务端不得不在“低延迟短请求”和“质量优先长请求”之间划出两条队列，而两条队列共享同一张卡时，显存档位成了真正的仲裁者。</p>\n<p>具体到一个高并发场景：一批 8 张 1024 分辨率图像、条件提示较长、启用无分类器引导（CFG）。CFG 意味着每步要跑无条件与有条件两条分支，显存约为单分支的两倍批激活；若再叠加几十步的循环，中间激活的峰值直接把批大小压到个位数，吞吐被显存而非算力限制。此时调度器的选择空间极窄：要么牺牲批大小换显存，要么牺牲步数换延迟，两条路都在削减服务质量。这就是一致性模型出现之前的现场——不是某个算子不够快，而是生成范式本身把延迟与吞吐写死在了采样步数上。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-2\">二 · 旧方案的三条路，各自撞在哪堵墙上</h3>\n<p>论文之前的主流做法可以归为三类，每一类都在同一堵墙上换了个撞法。</p>\n<ul>\n<li><b>快速采样器</b>：把连续时间积分离散化得更粗，用高阶求解器在较少步数内逼近同一轨迹。它降低了 <span class=\"inline-math\">N</span>，但没有改变“仍需迭代”的结构：每步依旧要前向、依旧要写中间激活、依旧要处理 CFG 双分支。步数降到个位数时，离散化误差与条件细节的退化开始显现，且不同提示词对步数的敏感度不一致，服务端很难给出统一的档位。</li>\n<li><b>蒸馏式少步生成</b>：用教师模型的轨迹监督学生，把多步压成几步。这条路直接攻击 <span class=\"inline-math\">N</span>，但早期方案往往依赖对抗训练来补足少步下的分布匹配，训练不稳定、调参成本高，且与既有扩散训练管线耦合松，复用预训练权重的路径不顺畅。</li>\n<li><b>工程侧压缩</b>：量化和缓存类手段降低单步的 <span class=\"inline-math\">C</span> 与 <span class=\"inline-math\">M</span>——这条线在别的条目里已经展开，此处只需指出它的边界：它优化的是乘子，不是 <span class=\"inline-math\">N</span> 本身。当 <span class=\"inline-math\">N</span> 仍是几十，量化带来的收益会被循环次数稀释；而当 <span class=\"inline-math\">N</span> 降到一，量化的收益才会完整地体现在端到端延迟上。</li>\n</ul>\n<p>三类方案的共同代价可以统一表述：延迟下界被 <span class=\"inline-math\">N</span> 锁定，显存峰值被 <span class=\"inline-math\">b·M</span> 与 CFG 双分支锁定，吞吐被两者的比值锁定。只要生成路径里还存在“迭代求解器”这一结构，调度器能动的只有批大小与步数档位这两个外部旋钮，而它们各自都带着质量惩罚。工程判断因此变得明确：需要的不是更好的求解器，而是一种把“轨迹上的任意点直接映射到终点”的函数，使 <span class=\"inline-math\">N</span> 从语义约束降级为可选档位。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-3\">三 · 为什么非改不可：SLO 与容量的算术</h3>\n<p>把上面的代价放进容量规划就看出紧迫性。设目标 SLO 为单请求 P99 延迟 <span class=\"inline-math\">L</span>，单卡在给定显存档位下的最大批为 <span class=\"inline-math\">b_max</span>，则单卡吞吐上限约为 <span class=\"inline-math\">b_max / (N·t_step + t_dec)</span>，其中 <span class=\"inline-math\">t_step</span> 是单步前向时间、<span class=\"inline-math\">t_dec</span> 是 VAE 解码时间。要满足 <span class=\"inline-math\">N·t_step + t_dec ≤ L</span>，在 <span class=\"inline-math\">t_dec</span> 不可压缩的前提下，<span class=\"inline-math\">N</span> 必须小到让前向项让位于解码项。反过来，若 <span class=\"inline-math\">N</span> 大，则 <span class=\"inline-math\">b_max</span> 必须大才能撑住吞吐，而 <span class=\"inline-math\">b_max</span> 又被 CFG 双分支的激活峰值压住——两个约束互相拉扯，容量规划的解空间迅速收窄到不可行区间。</p>\n<div class=\"formula\">$$\\text{吞吐}_{\\max}\\approx\\frac{b_{\\max}}{N\\cdot t_{\\text{step}}+t_{\\text{dec}}},\\qquad b_{\\max}\\le\\frac{\\text{显存档位}}{2\\cdot M_{\\text{act}}}$$</div>\n<p>这条算术解释了一个常见现象：同一张卡跑离线批处理时吞吐尚可，一旦切成在线低延迟队列，吞吐骤降。原因不是硬件变了，而是 <span class=\"inline-math\">L</span> 把 <span class=\"inline-math\">N</span> 的上界压死，<span class=\"inline-math\">b_max</span> 又因 CFG 被压死，两个上界相乘后剩下的可行域很窄。工程上常见的补救是“按最大批统一调度”，这恰恰是失败模式之一：一步档与多步档的显存与延迟特性不同，统一批大小会造成一步档显存浪费、多步档显存溢出，或者反过来让低延迟队列排进长循环请求而违约。非改不可的理由因此不是“想要更快”，而是“现有结构下 SLO 与容量算术无解”。</p>\n<p>再看一个具体例子：一个服务把提示词分为短条件与长条件两档，短条件走低延迟队列、长条件走质量队列。旧方案下两档都要跑完整采样循环，低延迟队列只能靠减步数勉强达标，长条件则因 CFG 双分支显存峰值被迫减小批，两条队列在同一张卡上争抢显存档位，调度器只能在超时率与回退率之间做取舍。监控面板上真正有信息量的指标不是平均延迟，而是每档步数、批大小、显存峰值、解码耗时与超时率的联合分布——它们共同刻画了 <span class=\"inline-math\">N</span> 与 <span class=\"inline-math\">b</span> 的可行域有多窄。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-4\">四 · 论文给出的结构替换：把迭代换成一次映射</h3>\n<p>一致性模型的做法是把生成路径从“沿轨迹积分”换成“直接预测轨迹终点”。它学习一个一致性函数 <span class=\"inline-math\">f(x,t)</span>，使同一概率流 ODE 轨迹上的任意点 <span class=\"inline-math\">(x_t,t)</span> 都映射到同一终点 <span class=\"inline-math\">x_ε</span>。部署侧的直接后果是：推理路径不再包含迭代求解器，一次前向即得终点估计，延迟由单次前向与 VAE 解码主导；需要质量折中时才在时间网格上循环调用，循环次数成为调度器可选的档位而非模型语义。</p>\n<p>训练侧用相邻时刻自洽来约束这个函数，损失写成相邻两点的映射差：</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\mathrm{CD}}(\\theta)=\\mathbb{E}_{t\\sim\\mathcal{U}[\\epsilon,T],\\,x_{t+\\Delta t}}\\left[\\lambda(t)\\,\\big\\| f_\\theta(x_{t+\\Delta t},t+\\Delta t)-f_{\\theta^{-}}(x_t,t)\\big\\|_2^2 \\right]$$</div>\n<p>其中 <span class=\"inline-math\">\\(f_{\\theta^{-}}\\)</span> 是 EMA 目标网络，<span class=\"inline-math\">λ(t)</span> 是损失权重，时间步采样分布影响稳定性。这条式子对推理系统的意义在于它不依赖对抗训练：少步生成的质量由自洽约束给出，而不是由判别器博弈给出，训练管线的稳定性因此可预期，且能与既有扩散训练流程兼容。蒸馏阶段更进一步——冻结预训练扩散教师，用其 ODE 求解器生成相邻轨迹点对，学生复用教师参数初始化，把多步轨迹压成一步或少步映射。对已经拥有扩散权重的团队，这意味着不需要从头训练就能换掉推理结构。</p>\n<p>代价的转移要说清楚：一步档把 <span class=\"inline-math\">N</span> 从几十降到一，延迟乘子消失，吞吐分母里的 <span class=\"inline-math\">N·t_step</span> 退化为 <span class=\"inline-math\">t_step</span>，此时 VAE 解码成为端到端延迟的主要项之一，解码批大小与精度方案开始主导优化方向。显存侧，CFG 仍可把无条件与有条件样本拼成同一批一次前向，显存约为双分支的两倍批激活，因此 <span class=\"inline-math\">b_max</span> 的约束没有消失，只是从“步数×激活”变成“单次激活×2”。换句话说，结构替换解除的是延迟与吞吐的乘子约束，保留的是显存约束——这决定了服务端仍需按步数分档调度。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-5\">五 · 旧方案留下的失败模式，正是新结构的验收清单</h3>\n<p>把旧方案的痛点逐条对照，就能看出一致性模型在部署上必须回答的问题，而这些问题的答案构成了本卷后续部分的工程边界。</p>\n<ul>\n<li><b>一步不等于多步质量</b>：旧方案里减步数直接掉质量；新结构下一步档在复杂条件与高分辨率上细节可能不足，服务端必须保留回退多步档的路由，并记录回退比例与超时率。把一步档当作无条件等价于多步质量，是典型的误判。</li>\n<li><b>时间网格失配</b>：多步一致性采样在时间网格上交替去噪与重新加噪，网格与训练分布不一致会导致质量下降。旧方案里求解器的离散化误差问题，在新结构里转化为网格设计问题，性质相同但可控点不同。</li>\n<li><b>两阶段数据流混淆</b>：一致性训练从数据采样加噪取相邻点对，蒸馏阶段用教师 ODE 轨迹点对。把教师轨迹点对误用于从头训练会造成目标不一致——这是训练管线层面的失败模式，与推理侧的档位设计无关，但会直接决定蒸馏出的学生能否支撑一步档。</li>\n<li><b>统一批调度的陷阱</b>：一步档可增大批提升吞吐，多步档需减小批控制中间激活峰值。按最大批统一调度会同时制造显存溢出与 SLO 违约，旧方案下这个问题被 <span class=\"inline-math\">N</span> 的大乘子掩盖，新结构下它暴露得更直接。</li>\n</ul>\n<p>这些失败模式的共同点是：它们都不是数值精度或算子层面的问题，而是调度与档位层面的问题。旧方案的现场之所以非改不可，是因为 <span class=\"inline-math\">N</span> 把调度器的可行域压得太窄；新结构把 <span class=\"inline-math\">N</span> 变成档位后，可行域变宽，但宽出来的空间需要新的调度规则来填充——按步数分档、按显存档位截断批、按回退比例监控。工程判断落在这里：一致性模型解除的是生成范式的结构约束，它不自动解决调度问题，反而把调度问题从“能不能做”变成“怎么分档”。</p>\n<p>最后一个具体机制值得留在本部分末尾：条件生成时 CFG 的批合并。把无条件与有条件样本拼成同一批一次前向，避免了双分支的两次 kernel 启动与两次激活写回，代价是批内样本数翻倍、显存约为双分支的两倍批激活。在一步档下，这个代价相对可接受，因为循环次数已降到一；在多步档下，它仍是 <span class=\"inline-math\">b_max</span> 的主要约束。服务端因此需要按显存档位截断批大小并记录超时率——这条规则不是论文给的，而是旧方案现场逼出来的工程结论，也是后续讨论批调度与连续批处理时的起点。</p>\n<h3 id=\"paper-consistency-models-2023-sec-6\">六 · 先把“请求”拆成可测的向量，而不是一个 QPS</h3>\n<p>在一致性模型的服务侧，负载不能只用“每秒多少请求”描述。一步档与多步档在同一条队列里竞争显存与 SM，二者的代价结构完全不同：一步档的端到端时间由单次一致性函数前向加 VAE 解码构成，多步档则在时间网格上循环调用一致性函数，每步还要重新加噪。因此测量口径必须把请求展开成一个向量：输入条件长度（文本 token 数）、输出分辨率（决定 VAE 解码的激活规模）、步数档位、是否启用 CFG、批内并发样本数。缺任何一维，容量规划都会失真。</p>\n<p>设请求 <span>i</span> 的到达率为 <span>λ_i</span>，其服务时间近似为</p>\n<div class=\"formula\">$$T_i \\approx N_{\\text{step},i}\\cdot t_{\\text{fwd}}(B_i) + t_{\\text{vae}}(B_i\\cdot m_{\\text{cfg},i}) + t_{\\text{queue},i}$$</div>\n<p>其中 <span>N_step</span> 是一步档取 1、多步档取循环次数，<span>B_i</span> 是该请求实际占用的批内样本数，<span>m_cfg</span> 在 CFG 批合并时取 2。注意 <span>t_fwd</span> 不是常数：批越大，单次前向摊到每个样本的时间下降，但显存峰值上升，多步档的中间激活随步数累积。工程上要测的不是平均延迟，而是按档位分层的 P50/P99 与超时率，否则一步档的低延迟会被多步档的长尾淹没。</p>\n<p>具体例子：同一批 8 个请求，若全部走一步档，单次前向即可返回，显存峰值主要由批激活与 VAE 解码决定；若其中 2 个因复杂条件回退到多步档，这 2 个请求会在时间网格上循环，占用同一张卡的 SM 更久，队列里其余一步档请求的 P99 被拉高。测量时必须把“回退比例”作为一等指标记录下来，它是负载被方案反向塑造的直接证据。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-7\">七 · 输入长度分布与条件复杂度决定档位路由</h3>\n<p>一致性模型的输入是含噪样本与时间步嵌入，条件生成时还拼接文本条件嵌入。文本 token 数影响条件编码与注意力的计算量，但更关键的是它影响“一步档是否够用”。复杂条件（长提示、多对象、空间关系约束）在一档下单次前向容易丢失细节，服务端需要一条可判定的路由规则，而不是靠人工配置。</p>\n<p>可核查的测量口径是：对每个请求记录条件 token 数 <span>L</span>、负向提示是否存在、分辨率档位，并按 <span>L</span> 分桶统计一步档的“回退率”与“人工弃单率”。路由阈值应写成</p>\n<div class=\"formula\">$$\\text{route}(i)=\\begin{cases}\\text{1-step}, &amp; L_i\\le L^\\* \\ \\text{and}\\ r_i\\le r_{\\text{hi}}\\\\ \\text{multi-step}, &amp; \\text{otherwise}\\end{cases}$$</div>\n<p>其中 <span>r_i</span> 是分辨率相对基准的倍率，<span>L*</span> 与 <span>r_hi</span> 由离线分桶的回退率曲线确定，而不是拍脑袋。代价在于：多步档的循环次数直接乘在延迟上，若回退比例从低个位数上升到两位数，整卡吞吐按步数加权后显著下降。这就是负载塑造方案的一面——条件分布变复杂，方案被迫把更多流量推给多步档。</p>\n<p>反过来，方案也限制负载：一步档一旦对外承诺低延迟 SLO，产品侧就会倾向把短提示、固定分辨率的请求集中投放，长提示请求被引导到异步队列或降级到多步档。这种“负载整形”必须在容量模型里显式建模，否则按混合负载测出的吞吐会在真实流量下不可复现。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-8\">八 · 批大小、CFG 合并与显存峰值的三角约束</h3>\n<p>批调度按步数分档是这套方案的核心工程判断：一步档可以增大批以提升吞吐，因为只有一次前向，中间激活不随步数累积；多步档必须减小批以控制激活峰值，因为每一步的去噪输出都要保留到重新加噪，循环中显存占用是步数的函数。CFG 批合并把无条件与有条件样本拼成同一批一次前向，显存约为双分支的两倍批激活，这直接把可用批大小砍半。</p>\n<p>可核查口径是记录每次前向的 <span>B_eff = B·m_cfg</span>、显存峰值 <span>M_peak</span>、以及 <span>M_peak / M_card</span> 的占比。容量约束写成</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor \\frac{M_{\\text{card}}-M_{\\text{static}}-M_{\\text{vae}}}{m_{\\text{cfg}}\\cdot a_{\\text{act}}(N_{\\text{step}})}\\right\\rfloor$$</div>\n<p>其中 <span>a_act</span> 是单样本单步的激活字节数，随 <span>N_step</span> 增长。这个式子说明：多步档的 <span>B_max</span> 随步数近似反比下降，而一步档的 <span>B_max</span> 只受单步激活与 VAE 解码限制。工程代价是显式的——把多步档的批调大，短期吞吐上升，但显存溢出会导致整批重试，P99 反而恶化；把一步档的批调小，显存安全但 SM 利用率不足，单位 token 成本上升。</p>\n<p>具体例子：同一张卡上，一步档在 CFG 合并后 <span>B_eff</span> 翻倍，若原本批为 <span>B</span>，合并后等效批为 <span>2B</span>，显存峰值接近线性上升；此时若仍按未合并的批大小调度，就会在解码阶段触发溢出。正确做法是把 CFG 合并后的等效批作为调度器的第一类输入，而不是事后补救。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-9\">九 · SLO 分层与长尾：一步档不是万能档</h3>\n<p>一步档的价值在于把单请求延迟从“步数 × 单步时间”压缩到“单次前向 + 解码”，但它不是无条件等价于多步质量。复杂条件与高分辨率下细节退化，服务端必须保留回退多步档的路由与监控。SLO 因此要分层：一步档承诺低延迟短请求的 P99，多步档承诺质量优先请求的完成时限，两者共享同一批 GPU 但队列隔离。</p>\n<p>长尾的来源有三类：一是回退请求，步数从 1 跳到多步，延迟成倍增加；二是 VAE 解码，输出阶段的主要开销之一，解码批大小与精度方案影响端到端延迟；三是 CFG 合并导致的显存抖动，批内样本数翻倍后调度器被迫拆分批次，增加 kernel 启动与队列等待。测量口径要求分别统计这三类的占比与对 P99 的贡献，而不是只看总超时率。</p>\n<p>可核查的做法是给每个请求打上 <span>(档位, 回退标志, 解码批大小, 是否 CFG 合并)</span> 四元标签，按标签聚合延迟分位数。若某标签的 P99 显著高于同档位其他标签，说明该路径存在结构性瓶颈，应优先调整路由阈值或解码批策略，而不是盲目扩容。代价判断也在这里：扩容能压低队列等待，但压不下单请求内的步数循环与解码时间，对回退长尾无效。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-10\">十 · 负载与方案的相互塑造：可复现的测量清单</h3>\n<p>负载塑造方案：条件分布变复杂、分辨率提高，回退比例上升，多步档流量占比提高，整卡有效吞吐按步数加权下降，容量规划必须按“步数加权请求”而非原始 QPS 计算。方案限制负载：一步档的低延迟承诺吸引短请求集中投放，长请求被引导到异步或降级路径，真实流量因此偏离离线压测的混合比例。二者互为因果，任何容量结论都必须标注测量时的负载向量。</p>\n<p>可核查的测量清单包括：按档位分层的请求数、步数分布、回退比例、CFG 合并比例、批大小分布、显存峰值分位数、VAE 解码耗时分位数、超时率与弃单率。每一项都要能对应到调度器的一个可调参数，否则测了也无法行动。例如回退比例对应路由阈值 <span>L*</span>，显存峰值对应 <span>B_max</span> 公式中的 <span>a_act</span> 与 <span>m_cfg</span>，解码耗时对应解码批与精度方案。</p>\n<p>具体例子：若监控显示一步档 P99 稳定但多步档超时率上升，先看回退比例是否随条件长度漂移，再看多步档的批是否因显存被压得过小导致 SM 空转。前者是负载变化，后者是方案自限。两种情况的处置完全不同：前者调路由与产品侧整形，后者调批调度与激活复用。把这两类原因混在一起，就会得出“加卡”这种对长尾无效的结论。</p>\n<p>最后落在机制上：一致性模型的服务化把“步数”变成了一个可调度的离散档位，负载向量中的条件长度与分辨率决定档位选择，档位选择又反过来决定批大小、显存峰值与队列分层。测量口径必须围绕这个闭环设计——记录档位、回退、CFG 合并与解码批四元标签，按标签聚合分位数，才能让容量规划与 SLO 承诺在同一套可复现的数字上对齐。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-11\">十一 · 负载如何反向约束步数档位：一步与多步的边界条件</h3>\n<p>一致性模型把服务端从“迭代求解器主导”改成“档位主导”，但档位一旦落到队列里，负载形态就会反过来改写方案本身。一步档的端到端延迟由单次前向与 VAE 解码两段构成，中间没有时间网格循环，因此它的批大小上限几乎只由激活峰值与解码显存决定；多步档则在时间网格上交替执行“一致性函数估计终点—按调度重新加噪”，每多一步就多一次前向与一次重加噪，延迟近似随步数线性叠加。设一步档单请求延迟为 <span class=\"formula-inline\">$L_1 = t_{\\text{fwd}}(B) + t_{\\text{dec}}(B)$</span>，多步档为 <span class=\"formula-inline\">$L_K \\approx K\\cdot t_{\\text{fwd}}(B) + t_{\\text{dec}}(B)$</span>，其中 <span class=\"formula-inline\">$t_{\\text{fwd}}$</span> 随批大小 <span class=\"formula-inline\">$B$</span> 上升但摊薄效应递减——这决定了“增大批换吞吐”只在一步档成立，多步档增大批会同时抬高单请求延迟与激活峰值，SLO 与显存两头受压。</p>\n<p>失效条件集中在两处。其一是时间网格与训练分布失配：多步档的网格点若偏离训练时连续时间步采样所覆盖的区间，重新加噪后的点不再落在同一 ODE 轨迹附近，一致性函数的终点估计开始漂移，表现为质量随步数不升反降；此时“加步数换质量”的直觉失效，调度器按步数分档的假设被打破。其二是条件复杂度：一步档在复杂提示与高分辨率下细节不足，必须保留回退多步档的路由，回退比例本身成为容量规划的一等指标——回退比例上升意味着有效步数分布右移，原先按一步档估算的算力预算立刻不够。CFG 批合并进一步放大这一效应：无条件与有条件样本拼成同一批一次前向，显存约为双分支的两倍批激活，按显存档位截断批大小后，一步档的吞吐优势被压缩，多步档则可能被迫降到极小批，kernel 启动开销占比上升。</p>\n<p>可核查的测量口径必须把“档位”作为第一维切分，而不是只报总体均值。建议按以下口径采集，缺一项就无法判断瓶颈在步数、批还是解码：</p>\n<table class=\"mini\"><thead><tr><th>口径</th><th>采集方式</th><th>用途</th></tr></thead><tbody><tr><td>每档步数分布</td><td>按请求记录实际循环次数，含回退后的步数</td><td>识别网格失配与回退比例漂移</td></tr><tr><td>批大小与显存峰值</td><td>按档位分别统计批内样本数与激活峰值</td><td>判断是否被 CFG 合并或解码显存卡住</td></tr><tr><td>前向与解码耗时拆分</td><td>分别计时单次前向与 VAE 解码</td><td>定位延迟主导段，决定是否调精度</td></tr><tr><td>单请求延迟分位数</td><td>P50/P99 按档位分开报</td><td>长尾来自多步档还是解码抖动</td></tr><tr><td>超时率与回退率</td><td>按队列深度与档位交叉统计</td><td>容量规划与路由阈值的直接输入</td></tr></tbody></table>\n<p>这张表的关键在于“按档位分开报”：把一步档与多步档混在一起求平均，会同时掩盖一步档的显存截断与多步档的网格失配。工程判断上，一步档应配大批、低延迟队列，多步档应配小批、吞吐队列并单独监控失败率；当回退率或超时率越过阈值，优先检查时间网格是否与训练分布对齐、CFG 批合并是否把批大小压到摊薄失效的区间，而不是先调调度策略。</p>\n<h3 id=\"paper-consistency-models-2023-sec-12\">十二 · 一致性函数前向的算子骨架</h3>\n<p>一致性模型的推理路径只有一条主干：把 <code>(x_t, t, c)</code> 送进骨干网络，一次前向吐出 <code>x_ε</code>。落到 kernel 层面，这条主干由四类算子拼成——时间步嵌入的 MLP、条件交叉注意力、主干卷积或 DiT 的 attention/MLP 块、以及输出投影。与多步扩散不同，这里没有求解器循环，也就没有每步的 kernel 启动税；但代价转移到单次前向必须承载全部计算量，因此单请求延迟对 kernel 效率的敏感度远高于多步路径（多步路径可以把固定开销摊薄到几十次调用上）。工程含义很直接：一步档的 SLO 由最慢的那个 kernel 决定，而不是由平均 kernel 决定。</p>\n<p>以 DiT 骨干为例，一个 block 的前向可写成伪代码思路：</p>\n<div class=\"formula\">$$h \\leftarrow h + \\mathrm{Attn}(\\mathrm{LN}(h) + \\mathrm{Emb}(t) + \\mathrm{Cond}(c)),\\quad h \\leftarrow h + \\mathrm{MLP}(\\mathrm{LN}(h))$$</div>\n<p>逐项解释：<code>Emb(t)</code> 是时间步的正弦嵌入经两层 MLP 后的调制向量，它决定同一批内不同 <code>t</code> 的样本走不同调制；<code>Cond(c)</code> 是文本条件嵌入，CFG 合并时它与无条件嵌入在同一批内共存，因此 batch 维实际是 <code>2B</code>；<code>Attn</code> 的 QKV 投影与 softmax 是显存带宽最吃紧的部分，因为中间激活要往返 HBM。推理系统代价上，一步档的显存峰值主要由这批 <code>2B</code> 激活与 VAE 解码缓冲共同决定，而带宽压力集中在 attention 的读写上；这解释了为什么一步档“算力不缺、带宽吃紧”，批大小上调时吞吐上升但延迟分位数恶化。</p>\n<p>具体例子：服务端把一步档的批设为 <code>B</code>，CFG 合并后实际前向批为 <code>2B</code>。若显存档位只够 <code>2B</code> 的激活，则有效吞吐是 <code>B</code> 而非 <code>2B</code>——批调度必须按合并后的真实批计算，否则会在 attention 峰值处溢出。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-13\">十三 · 数据类型：FP16 / BF16 / FP8 / NVFP4 的取舍</h3>\n<p>一致性函数输出的是轨迹终点估计，数值范围与扩散模型去噪网络的输出同量级，因此精度选择的核心不是“能不能算”，而是“终点估计的误差会不会被 VAE 解码放大”。FP16 的尾数位多、动态范围窄，适合激活值分布集中的层；BF16 动态范围与 FP32 同阶但尾数只有 8 位，在时间步嵌入与调制向量这类小数值上更稳，代价是量化噪声更大。工程上常见做法是权重与激活统一 BF16 走主干，把对数值敏感的归一化与 softmax 累加留在 FP32。</p>\n<p>FP8 分 E4M3 与 E5M2 两种格式：E4M3 尾数多、范围窄，适合权重与激活；E5M2 范围大、尾数少，适合梯度类或动态范围跨度大的张量。推理侧用 FP8 的收益是显存占用与带宽双减，代价是需要在每个 block 前插入缩放（scale）计算，缩放因子本身要占寄存器与一次额外乘法。NVFP4 把尾数压到 4 位，必须配块级缩放（每 16 或 32 个元素一个 scale）才能保住动态范围；对一致性模型而言，NVFP4 的风险点在于一步档没有多步迭代来“平均掉”量化误差，单次前向的误差直接进入 VAE 解码，因此 NVFP4 更适合权重侧、激活侧需按层做敏感度筛查。</p>\n<table class=\"mini\"><thead><tr><th>格式</th><th>尾数/范围特征</th><th>推理侧主要代价</th><th>适配位置</th></tr></thead><tbody><tr><td>FP16</td><td>尾数多、范围窄</td><td>溢出风险需 clipping</td><td>激活、attention 输出</td></tr><tr><td>BF16</td><td>范围同 FP32、尾数少</td><td>量化噪声偏大</td><td>主干权重与激活默认档</td></tr><tr><td>FP8 E4M3</td><td>尾数中等、范围窄</td><td>每 block 缩放开销</td><td>权重、线性层输入</td></tr><tr><td>NVFP4</td><td>4 位尾数、需块缩放</td><td>缩放元数据与解包</td><td>权重侧优先，激活需筛查</td></tr></tbody></table>\n<p>具体例子：把 DiT 主干的线性层权重降到 FP8、激活保持 BF16，显存下降主要来自权重常驻部分，而 attention 的激活读写仍是 BF16 带宽；若把激活也降到 FP8，带宽收益才真正体现在 attention 上，但需要验证一步档在复杂条件上的细节退化是否触发回退多步档。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-14\">十四 · 累加精度与误差传播</h3>\n<p>低精度乘法不等于低精度累加。Tensor Core 的 MMA 指令在内部以更高精度累加（FP32 累加是常见配置），但累加结果写回寄存器或 TMEM 时又会被截断到目标格式。误差因此有两个来源：输入量化的舍入误差，与累加结果的截断误差。对一致性模型，误差传播路径是“单次前向的终点估计误差 → VAE 解码后的像素误差”，没有多步迭代的误差抵消机制，所以累加精度的影响比多步扩散更直接。</p>\n<div class=\"formula\">$$\\hat{x}_\\epsilon = f_\\theta(x_t,t) + \\varepsilon_{\\mathrm{quant}},\\quad \\|\\varepsilon_{\\mathrm{quant}}\\| \\approx \\sqrt{K}\\,\\delta_{\\mathrm{acc}}$$</div>\n<p>逐项解释：<code>K</code> 是参与累加的元素数（即 reduction 长度，等于隐藏维或注意力头维），<code>δ_acc</code> 是单次累加的截断步长，误差按随机游走近似随 <code>√K</code> 增长。这条式子给出两个工程判断：其一，reduction 维度大的层（MLP 的隐层投影、attention 的 value 累加）对累加精度最敏感；其二，把累加器留在 FP32、只在写回时降到 BF16/FP8，比全程低精度累加的误差小一个量级，代价是寄存器压力与 TMEM 占用上升。</p>\n<p>推理系统代价上，FP32 累加器占用更多寄存器，会压低 occupancy，进而影响 attention 这类带宽受限 kernel 的延迟；在 Blackwell 上这部分压力可以转移到 TMEM，但 TMEM 容量有限，block 内并发 warp 数受其约束。具体例子：attention 的 <code>QK^T</code> 与 <code>PV</code> 两次 MMA 若都用 FP32 累加，softmax 前的分数矩阵精度足够，但 TMEM 占用上升会限制同时驻留的 block 数；把 <code>PV</code> 的累加降到 BF16 可换回并发度，代价是 value 聚合的尾数噪声增大，需在一步档质量监控里观察回退比例。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-15\">十五 · Blackwell 特性：tcgen05、TMEM、2-SM MMA</h3>\n<p>Blackwell 的第五代 Tensor Core 把 MMA 的发起方式从 warp 级改成 warpgroup/CTA 级，tcgen05 指令族让一个 CTA 甚至一对 CTA 协同发起大块矩阵乘，累加器落在 TMEM（Tensor Memory）而不是寄存器堆。对一致性模型推理的直接意义有三点：其一，单次前向里最大的两个 GEMM（QKV 投影与 MLP 隐层）可以用更大的 tile，减少 HBM 往返次数，正好对上一步档“带宽吃紧”的瓶颈；其二，TMEM 把累加器从寄存器剥离，缓解 FP32 累加的寄存器压力，使高精度累加与高 occupancy 可以并存；其三，2-SM MMA 让两个 SM 共享一次 MMA 的输入分片，把单个大 GEMM 拆到两个 SM 上并行，缩短单 kernel 的关键路径——这对一步档的尾延迟尤其重要，因为一步档没有循环可以隐藏长 kernel。</p>\n<div class=\"formula\">$$\\text{latency}_{\\text{step}} \\approx \\sum_{k}\\big(\\text{GEMM}_k + \\text{mem}_k\\big) + \\text{decode}_{\\text{VAE}}$$</div>\n<p>逐项解释：求和遍历主干各 kernel，<code>GEMM_k</code> 是第 k 个矩阵乘的耗时，<code>mem_k</code> 是其数据搬运耗时，<code>decode_VAE</code> 是输出解码。tcgen05 与 2-SM MMA 压缩的是 <code>GEMM_k</code> 与 <code>mem_k</code> 两项，但对 <code>decode_VAE</code> 无影响——这解释了为什么一步档优化到后期，VAE 解码会成为端到端延迟的固定底噪，需要单独用批大小与解码精度去调。</p>\n<p>具体例子：把主干最大的 MLP 隐层 GEMM 用 2-SM MMA 切成两半并行，单 kernel 关键路径缩短，但要求两个 SM 的输入分片同时就绪，对批内样本的时间步分布提出约束——若同一批内 <code>t</code> 差异过大，调制向量的分支会破坏分片的规则性，因此批内按时间步档位分组（一步档天然只有 <code>t=T</code>）反而有利于 2-SM MMA 的利用率。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-16\">十六 · 精度方案与步数档位的耦合</h3>\n<p>精度选择不能脱离步数档位单独决策。一步档的误差没有迭代平均，低精度带来的终点偏差直接可见；多步档在时间网格上反复调用一致性函数，每步的量化误差会被重新加噪与再映射部分吸收，但也可能累积成网格失配之外的额外漂移。工程上的做法是按档位分精度：一步档走 BF16 主干 + FP8 权重（保守），多步档可尝试 FP8 激活 + NVFP4 权重（激进），并用回退比例与超时率作为切换信号。</p>\n<p>推理系统代价的权衡可以写成：精度每降一档，显存与带宽收益按格式位宽比例释放，但质量风险按档位放大。具体例子：一步档在复杂条件上细节不足时，服务端回退多步档；若多步档同时用了更激进的 NVFP4 激活，回退后的质量可能仍不达标，形成“回退也救不回来”的死角。因此精度档位与步数档位必须联合标定，而不是各自独立调优。</p>\n<p>监控上要记录的不是单一精度开关，而是每档的精度组合、显存峰值、回退比例与超时率四条线；其中回退比例是精度方案是否过激的直接证据——它上升说明一步档的终点估计误差已经越过质量阈值，此时应回退精度而非继续压位宽。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-17\">十七 · 数值稳定性的两个具体机制</h3>\n<p>第一个机制是时间步嵌入的数值范围。正弦嵌入在高频分量上数值跨度大，若直接降到 FP8 E4M3 会因范围窄而溢出，需先做归一化或用 E5M2；调制向量经 MLP 后进入每个 block 的 scale/shift，误差会逐 block 放大。工程判断是：时间步嵌入与调制链路留在 BF16 或 FP16，不参与 FP8 压缩，这条链路的元素数少、带宽占比低，压缩收益不抵风险。</p>\n<p>第二个机制是 attention softmax 的累加。softmax 需要先求行最大值再求指数和，两步都是 reduction；若分数矩阵已是 FP8，行最大值与指数和的累加必须留在 FP32，否则指数项在低精度下会丢失小项，导致注意力分布偏移。这与多步扩散的 attention 处理同源，但一步档没有后续步骤修正，偏移直接进入输出。具体例子：CFG 合并批中无条件与有条件样本共享同一 softmax kernel，若两者分数分布差异大，统一的缩放因子会让一侧溢出，需按样本或按头做缩放，代价是缩放元数据增加一次读写。</p>\n<p>落到工程判断上：一致性模型推理的精度方案应以“链路分段”而非“全局一刀切”来设计——把数值敏感的嵌入与 softmax 累加留在高精度，把带宽密集的权重与线性层输入压到 FP8/NVFP4，再用 Blackwell 的 TMEM 承接 FP32 累加器以保住 occupancy。这条分段的边界，就是一步档延迟与质量的实际平衡点。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-18\">十八 · 精度选择的边界：一步档的数值风险与 Blackwell 数据通路</h3>\n<p>一致性模型的一步档把整条 ODE 轨迹压缩成单次前向，这使数值精度问题从“迭代累积误差”变成“单次映射误差”：没有后续步骤去修正舍入偏差，终点估计直接进入 VAE 解码。一致性损失约束的是相邻时刻映射的自洽性，$$\\mathcal{L}_{\\mathrm{CD}}=\\mathbb{E}\\big[\\lambda(t)\\|f_\\theta(x_{t+\\Delta t},t+\\Delta t)-f_{\\theta^-}(x_t,t)\\|_2^2\\big]$$其中 λ(t) 在 t 接近 ε 时通常放大权重，意味着终点附近的微小数值偏差被损失函数重点惩罚，但推理时并不存在这个惩罚项。工程判断是：一步档的激活量化误差必须按“终点误差”而非“单层误差”来评估，FP8 或 NVFP4 激活在 U-Net/DiT 的末端 block 上造成的偏差会直接体现在像素细节上，而多步档至少还有重新加噪的机会把偏差摊回轨迹。</p>\n<p>Blackwell 的 tcgen05 与 TMEM 改变了这个权衡的形状。第五代 Tensor Core 的 2-SM MMA 让两个 SM 协作完成一次大矩阵乘，累加器驻留 TMEM 而非寄存器堆，单次 MMA 的 K 维累加链更长；对一致性函数这种“输入含时间步嵌入、输出直接回归终点”的结构，末端几层的 GEMM 往往是小 M、大 K 形状，2-SM 协作能提高 Tensor Core 占用率，但 TMEM 的累加精度档位选择（FP32 累加 vs 更低精度累加）直接决定终点估计的偏差量级。若为吞吐把累加降到 FP16，误差会随 K 维线性放大，而一步档没有迭代平均来抵消它；因此末端 block 应保留 FP32 累加，前端 block 可放宽到 FP8 输入配 FP32 累加，形成分层精度策略。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>典型精度配置</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>一步档</td><td>权重 NVFP4/FP8，末端 FP32 累加</td><td>单次前向 + VAE 解码主导延迟，批可放大</td><td>复杂条件/高分辨率细节退化，需回退</td></tr><tr><td>多步档</td><td>权重 FP8，全链 FP32 累加</td><td>循环调用带来 kernel 启动与激活峰值</td><td>时间网格与训练分布失配</td></tr></tbody></table>\n<p>系统代价落在显存与带宽两侧：CFG 批合并使批内样本翻倍，激活显存约为双分支的两倍，NVFP4 权重能压低权重占用但激活仍按批规模线性增长，TMEM 容量则限制单次 2-SM MMA 的 tile 尺寸，批过大时 tile 切分增多、TMEM 复用率下降。一个具体例子：一步档在 FP8 权重、FP32 累加下把批放大以提吞吐，但若把末端 block 也切到 FP8 累加，终点样本在高频纹理上出现块状偏差，服务端只能靠回退多步档补救，回退比例上升会吃掉一步档的延迟收益。边界因此清晰：Blackwell 特性放大的是前端吞吐，末端数值通路必须保守，一步档的精度预算应按“无修正机会”来分配。</p>\n<h3 id=\"paper-consistency-models-2023-sec-19\">十九 · 显存账本的三个户头：权重、激活、KV 类中间态</h3>\n<p>在一致性模型的服务路径上，显存不是一个数字，而是三本互不相同的账。第一本是权重账：一致性函数以 U-Net 或 DiT 为骨干，参数在整段服务周期内常驻，其字节数由参数量与权重精度决定，与批大小、步数档位无关。第二本是激活账：单次前向中每一层保留的张量，随批大小线性增长，随分辨率（潜空间 token 数）近似平方增长，是批调度真正能调节的那部分。第三本是 KV 类中间态账：扩散主路径没有自回归解码那种逐 token 增长的 KV cache，但多步档在时间网格上循环时，若把每步的中间结果或条件嵌入缓存下来复用，就会形成一组“跨步驻留”的张量；CFG 批合并又把条件与无条件两路拼进同一批，使这批驻留翻倍。三本账的增长率完全不同，混在一起算就会得出错误结论。</p>\n<p>把三本账写成可复算的形式。设参数量 $P$、权重每元素字节 $b_w$、批大小 $B$、潜空间 token 数 $N$、每 token 每层激活字节 $b_a$、层数 $L$、跨步驻留张量数 $S$、CFG 路数 $C\\in\\{1,2\\}$，则峰值显存近似为：</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\underbrace{P\\,b_w}_{\\text{权重}} + \\underbrace{B\\,N\\,L\\,b_a\\,k}_{\\text{激活（含临时缓冲系数 }k\\text{）}} + \\underbrace{B\\,N\\,S\\,b_s\\,C}_{\\text{跨步驻留}} + M_{\\text{VAE}}$$</div>\n<p>其中 $k$ 是算子融合与临时缓冲带来的放大系数，$M_{\\text{VAE}}$ 是解码阶段单独占用的显存。这个式子的工程价值在于：它把“能不能加批”变成一个可解的线性不等式——给定显存档位，$B$ 的上界由激活项与驻留项共同决定，而权重项是常数偏移。一步档的 $S=0$，多步档的 $S&gt;0$，这就是为什么同一个模型在两个档位上能承载的批大小不同，也是“按最大批统一调度”必然出问题的算术根源。</p>\n<p>举一个可复算的例子（数值为假设，仅用于演示结构，不代表实测）：若权重以 FP8 存放、参数量取 10 亿量级，权重项约 1 GB；潜空间 token 数取 4096、层数取 32、激活每 token 每层 2 字节、$k$ 取 2，则单样本激活约 $4096\\times32\\times2\\times2 \\approx 0.5$ MB 量级乘以批大小；跨步驻留若每步保留 4 个张量、每张量每 token 2 字节，单样本驻留约 $4096\\times4\\times2 \\approx 32$ KB 乘以步数与 CFG 路数。可以看到，权重项在低批时主导，激活项在高批时主导，两条曲线的交点就是该档位的最优批大小附近。真正的容量规划必须按档位分别解这个不等式，而不是拿一个全局批大小套所有请求。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-20\">二十 · 分页与复用：把跨步驻留变成可管理的池</h3>\n<p>多步档的跨步驻留张量具有“生命周期短、尺寸固定、按步申请释放”的特征，非常适合分页管理。做法是把驻留区切成固定大小的页（例如按 token 块对齐），每一步的去噪与重新加噪只申请当前步需要的页，用完即还入池；池的容量按档位预设上限，超限时触发批截断而不是 OOM。这与自回归推理中的分页 KV cache 在机制上同源——都是把变长、短命的中间态从“整块预分配”改为“按需借还”，差别只在于扩散侧的页尺寸由潜空间 token 网格决定，且页的存活期以步为单位而非以 token 为单位。</p>\n<p>复用则发生在两个层面。其一是条件嵌入复用：文本提示编码后的条件张量在同一请求的所有步之间不变，应当只算一次并常驻，而不是每步重算；这省下的不是显存而是算力与带宽，但在多步档里它同时减少了每步的临时激活峰值。其二是 CFG 批合并的复用：把无条件与有条件样本拼成同一批一次前向，显存约为双分支的两倍批激活，但换来的是单次 kernel 启动与更高的 SM 占用率；工程判断是——当显存档位允许时合并，当激活项已经逼近上限时退回双分支串行，用时间换空间。这个开关应当由调度器按当前池水位动态决定，而不是写死在配置里。</p>\n<p>代价要算清楚。分页带来的额外开销是页表查询与借还的元数据操作，在步数很少的一步档里这部分开销占比不可忽略，因此一步档通常不值得分页，直接整块分配更快。复用条件嵌入的代价是常驻显存增加一份条件张量，对高并发、短提示的负载，这份常驻会挤占激活预算，需要按请求平均提示长度估算。CFG 合并的代价是批内样本数翻倍导致的激活峰值抬升，若显存水位已高，合并会让批大小被迫减半，吞吐反而下降——这是一个需要实测拐点的取舍，材料未给出具体数字，只能定性判断方向。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-21\">二十一 · 压缩：精度换容量，但要盯住一步档的质量</h3>\n<p>权重压缩是最直接的一本账。推理侧可考虑 FP8/NVFP4 权重与激活以降低显存并提升吞吐，但需验证一步档质量——这句话的工程含义是：一步档只有一次前向，数值误差没有多步迭代的自我修正机会，量化噪声会直接进入输出，而多步档在每步重新加噪的过程中对误差有一定平滑作用。因此压缩策略应当按档位分化：多步档可以更激进地压激活，一步档应优先保证权重与关键层的数值保真，把压缩预算留给非敏感层。</p>\n<p>激活压缩的收益比权重压缩更依赖批大小。权重项是常数，压缩它只降低基线；激活项随 $B$ 线性增长，压缩它直接抬高批大小上界，从而抬高吞吐。这就是为什么在显存受限的服务场景里，激活量化的边际收益往往高于权重量化——但代价是数值风险集中在输出质量上，且需要校准数据覆盖真实提示分布。跨步驻留张量的压缩则要谨慎：它们在步与步之间被反复读写，量化误差会累积，且驻留张量往往承载的是轨迹信息而非最终输出，误差传播路径更长。</p>\n<p>一个具体例子：若把激活从 16 位压到 8 位，激活项减半，按第一节的不等式，批大小上界大约翻倍（在激活主导的区间内），吞吐随之提升；但若一步档在复杂条件上本已细节不足，压缩会进一步放大退化，服务端必须保留回退多步档的路由并监控回退比例。压缩不是免费的容量，它是用质量换容量，账本上必须同时记两栏。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-22\">二十二 · 卸载：把冷数据挪出 HBM，代价是带宽</h3>\n<p>卸载的适用对象是权重中访问频率低的部分，以及一步档根本用不到的组件。典型场景是同一张卡上同时驻留一步档与多步档所需的不同组件，或者教师模型仅在蒸馏离线阶段需要、在线服务不需要。把冷权重放到主机内存或远端存储，按需换入，能把常驻权重项从 HBM 账本上削掉一块，为激活腾出空间。但卸载的代价是 PCIe 或互连带宽：一次换入的字节数除以链路带宽就是额外延迟，若换入发生在请求关键路径上，单请求延迟会被这条链路主导。</p>\n<p>工程判断的准则是：只卸载“每请求至多换入一次”且“换入量远小于该请求总算力开销”的组件。若某组件每步都要换入，带宽开销会随步数线性叠加，卸载就变成负优化。对于 NVL72 这类机架级系统，节点间带宽远高于节点内到主机的链路，把冷组件放到邻近节点的 HBM 而非主机内存，能把换入延迟压下来——这属于并行与通信拓扑的范畴，此处只指出卸载决策必须与拓扑一起算，不能只看容量。</p>\n<p>卸载还会改变显存账本的结构：权重项不再是常数，而是“常驻部分 + 可换入部分”，峰值显存取决于换入时刻的瞬时占用。这意味着容量规划要按最坏换入时刻算，而不是按稳态算。多步档若在循环中触发换入，峰值会出现在换入与激活叠加的瞬间，这个瞬时峰值往往比稳态高出一截，是 OOM 的常见来源。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-23\">二十三 · 带宽瓶颈在哪：HBM3e 容量与流量的分开算</h3>\n<p>容量与带宽是两本账，不能混。HBM3e 的容量决定能放多少权重、激活与驻留，带宽决定每步前向能多快把权重与激活搬过计算单元。一致性模型的一步档是典型的“权重带宽受限”形态：单次前向要读一遍参与计算的权重，算力利用率取决于权重能否被及时喂入，批大小太小时权重读取摊薄不足，带宽成为瓶颈；批大小增大后，激活读写占比上升，瓶颈从权重转向激活。多步档则是“激活带宽受限”形态：每步都要读写跨步驻留与重新加噪的张量，步数越多，这部分流量越主导。</p>\n<p>把流量写成式子。设每步需读取的权重字节 $W$、激活读写字节 $A(B)$、驻留读写字节 $R(B,S)$，步数 $n$，则单请求的显存流量近似为：</p>\n<div class=\"formula\">$$Q \\approx n\\cdot\\big(W + A(B) + R(B,S)\\big)$$</div>\n<p>端到端时间下界为 $Q$ 除以有效带宽。这个式子的用途是判断优化方向：若 $W$ 主导，应提高批大小摊薄权重读取，或用更低精度权重减少 $W$；若 $A(B)$ 主导，应做算子融合减少中间张量落盘，或压缩激活；若 $R(B,S)$ 主导，应减少跨步驻留张量数 $S$ 或改用分页按需读写。三种主导对应三种完全不同的优化手段，误判方向会把工程投入浪费在错误的环节上。</p>\n<p>HBM3e 容量的算法已在第一节给出框架，这里补一条工程细节：容量规划要按“档位 × 并发 × 峰值时刻”三维取值，而不是按平均。一步档的峰值出现在单次前向的激活峰值处，多步档的峰值出现在某一步的驻留与激活叠加处，CFG 合并会把这两个峰值都抬高。服务端监控指标中的“显存峰值”必须按档位分别采集，否则平均值会掩盖多步档的瞬时尖峰，导致调度器误判可用容量。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-24\">二十四 · 一个可复算的显存预算：从不等式到调度参数</h3>\n<p>把前五节收束成一个可执行的预算流程。第一步，按档位确定 $n$（一步档 $n=1$，多步档 $n$ 由质量档位给定）、$S$（一步档为 0）、$C$（是否 CFG 合并）。第二步，用第一节的不等式解出该档位在给定显存档位下的最大批大小 $B_{\\max}$，并对权重项、激活项、驻留项分别留出安全余量（余量比例按峰值波动设定，材料未给出具体值，需按实测尖峰标定）。第三步，把 $B_{\\max}$ 与延迟目标一起代入吞吐估算：单请求时间由前向时间与 VAE 解码时间构成，批处理摊薄的是前向时间中的权重读取部分，解码时间随批线性增长，因此存在一个使吞吐最大的批大小，它通常小于 $B_{\\max}$。第四步，把这个批大小写进调度器的档位参数，并按池水位动态调整 CFG 合并开关与分页阈值。</p>\n<p>这个流程的关键在于它把“显存够不够”从经验判断变成可复算的不等式，把“批开多大”从拍脑袋变成受两个约束（显存上界与吞吐拐点）夹逼的区间。工程上最常见的错误是按最大批统一调度，忽视一步档与多步档的显存与延迟差异，结果是一步档显存溢出、多步档 SLO 违约，或者反过来——为多步档压低批大小，白白牺牲一步档的吞吐。按档位分账、按峰值留余量、按拐点定批，是这套预算方法能落地的前提。</p>\n<p>最后落在具体机制上：调度器应当在每次档位切换时重算该档位的 $B_{\\max}$ 与吞吐拐点，把结果写入队列的准入条件；当池水位超过阈值时，优先触发 CFG 合并回退与批截断，而不是等待 OOM 后重试。监控侧按档位分别记录步数、批大小、显存峰值、解码耗时与超时率，回退多步档的比例作为质量侧的健康指标——这条指标上升，说明一步档在当前负载下已触及质量边界，压缩或卸载策略需要重新标定。</p>\n<h3 id=\"paper-consistency-models-2023-sec-25\">二十五 · 从“步数档位”到调度原语：为什么扩散服务的批处理不能照搬自回归</h3>\n<p>一致性模型把单请求的推理路径压缩成一次或数次一致性函数前向，这改变了服务端调度问题的形状。自回归 LLM 的连续批处理之所以成立，是因为每个请求的迭代粒度是“一个 token”，迭代之间可以自由插入新请求、逐出已完成请求，KV cache 按 token 增长且可被分页管理。扩散请求的迭代粒度是“一个采样步”，一步档根本没有迭代——请求在队列里等待的是整批的成形，而不是逐步加入。这意味着连续批处理在一步档上退化为“批成形 + 单次前向 + VAE 解码”的三段式流水，调度器的核心决策从“每步插谁”变成“这一批凑多大、什么时候必须发车”。多步档则恢复了迭代结构：时间网格上的每一步都是一次一致性函数调用，批内样本共享同一时间网格，因此可以在步与步之间做请求进出，但代价是网格必须对齐——新加入的请求必须从当前网格时刻对应的噪声水平重新加噪，而不是从它自己的 x_T 开始，否则轨迹不自洽。</p>\n<p>把这件事写成调度伪代码的思路是：维护两个队列，低延迟队列 L 只接受一步档请求，吞吐队列 T 接受多步档请求；每轮调度先看 L 的队首等待时间是否逼近 SLO 预算，若是则立即以当前 L 中所有可服务请求成形一个批，不再等待；否则从 T 中按显存档位允许的最大批大小取请求，锁定时间网格后连续跑完该网格。批成形的约束是显存：批激活峰值近似正比于批大小乘以单样本中间激活，CFG 合并后批内样本数翻倍，因此有效批大小要按 <span class=\"formula\">$$B_{\\text{eff}} = \\min\\left(B_{\\text{slot}},\\,\\left\\lfloor \\frac{M_{\\text{free}} - M_{\\text{weight}} - M_{\\text{dec}}}{2\\,a_{\\text{act}}}\\right\\rfloor\\right)$$</span> 截断，其中 a_act 是单样本单次前向的激活占用，分母的 2 来自无条件/有条件拼接。这个式子的工程含义很直接：CFG 不是免费的，它把批容量砍半，而一步档本来就靠大批摊薄单请求的解码开销，所以条件生成的低延迟路径往往被迫在“批大小”和“CFG 质量”之间二选一。</p>\n<p>具体例子：一个文生图服务同时收到 40 个短提示请求和 6 个高质量长提示请求。若按最大批统一调度，40 个一步档请求会被塞进一个受 CFG 翻倍约束的批，显存峰值由解码阶段的 VAE 激活决定，一旦溢出就整批重试，尾延迟直接爆掉；正确做法是把一步档拆成两个中等批流水发车，多步档单独占用一个较小批并锁定网格，两类请求的显存峰值互不叠加。代价体现在吞吐上：拆批增加了 kernel 启动次数与权重重复读取，吞吐略降，但尾延迟从“整批重试”变成“单批超时”，这是可接受的交换。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-26\">二十六 · Chunked prefill 在扩散里的对应物：解码分块与网格分段</h3>\n<p>LLM 的 chunked prefill 把长 prompt 的预填切成小块与解码请求混批，目的是压平预填造成的长尾。扩散没有 prefill/decode 的二分，但有两个结构上同构的东西：VAE 解码和长时间网格。VAE 解码是输出阶段的主要开销之一，且它的显存占用与批大小强相关——解码一个大批的潜空间结果，激活峰值可能超过整段去噪前向。把解码按批内样本分块执行，每块解码完立即释放激活并返回结果，可以让解码阶段的显存峰值与去噪阶段解耦，代价是解码 kernel 的启动次数增加、权重重复加载，端到端延迟略微上升但尾延迟显著收敛。这就是扩散版的“chunked decode”：不是把计算切细以提升吞吐，而是把显存峰值切细以消除整批失败。</p>\n<p>多步档的对应物是网格分段。多步一致性采样在时间网格上交替去噪与重新加噪，若一次性锁定整个网格，则批内所有请求必须等到最后一步才能返回，队首等待时间等于整条网格的时长。把网格切成若干段、每段结束后允许已完成请求（例如提前达到质量阈值的请求）退出、允许新请求以当前段末时刻重新加噪加入，就把一个长批变成了若干个短批的流水。分段长度的选择是一个明确的取舍：段越短，请求进出越灵活、尾延迟越低，但每段都要重新做批成形与权重加载，吞吐下降；段越长则相反。工程判断是让段长与 SLO 预算挂钩——单段时长不应超过尾延迟预算的一个固定比例，使得任何请求最多跨越有限个段就能返回。</p>\n<p>公式上，把尾延迟目标写成批内最大等待的约束：若段长为 τ、请求在第 k 段加入，则其等待上界约为 (N_seg − k)·τ 加上自身段内计算与解码时间。调度器要保证这个上界不超过 SLO，等价于对每个请求记录其“剩余段数”并在段边界做准入控制。代价是显存：分段意味着同一时刻可能有两个段的激活共存（上一段未释放、下一段已分配），需要预留一份额外激活预算，这直接压缩了可用批大小。具体例子：一个 8 步网格切成 4 段、每段 2 步，批大小从 16 降到 12 以留出跨段激活余量，吞吐下降约四分之一，但队首等待从整条网格时长降到两段时长，尾延迟分位数明显收敛。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-27\">二十七 · 优先级与抢占：一步档与多步档的显存争夺</h3>\n<p>两类档位共享同一张卡时，冲突点是显存而不是算力。一步档请求的批可以很大，因为它的中间激活只存在一次前向的时长内；多步档请求的批必须小，因为激活要在整个网格期间保持存活（每步的去噪结果要作为下一步的输入）。当一步档的大批与多步档的长网格批同时驻留，显存峰值叠加，溢出风险落在多步档身上——它不能像一步档那样“算完就释放”。因此优先级策略不能只按请求到达时间排，而要按“显存驻留时长”排：一步档是短驻留、可抢占（抢占代价是丢弃当前批、重新成形），多步档是长驻留、抢占代价高（丢弃意味着整条网格重跑）。</p>\n<p>可操作的抢占机制是分级驱逐：当显存逼近上限时，先驱逐尚未发车的一步档批（它们还没开始计算，丢弃无损失），再驱逐已发车但处于解码阶段的一步档批（丢弃只损失一次前向），最后才对多步档做网格级检查点——在段边界保存当前噪声状态与网格位置，驱逐后可在稍后从检查点恢复，代价是重跑当前段。检查点的存储开销是每请求一份与潜空间同尺寸的噪声张量，相对于整批激活很小，但恢复时的重新加噪必须与训练分布一致，否则网格失配会降低质量，这是前文已经指出的失败模式在调度层的投影。</p>\n<p>代价核算要落到具体指标：抢占率、检查点恢复率、因抢占导致的回退多步档比例。一个具体例子：当一步档队列深度突然上涨（例如批量营销文案触发大量短提示），调度器若不加约束会让一步档批无限增大，挤掉正在跑网格的多步档，导致后者检查点恢复、质量下降、用户感知为“同一提示两次结果不一致”。正确做法是给多步档预留固定的显存配额（按最大网格批的激活峰值加检查点开销计算），一步档只能使用剩余配额，配额不足时一步档排队而非抢占。这牺牲了一步档的峰值吞吐，换来了多步档的质量稳定性。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-28\">二十八 · 分离式预填/解码在扩散服务里的映射</h3>\n<p>LLM 的分离式预填/解码把计算特性差异巨大的两个阶段放到不同资源池：预填是算力密集、解码是访存密集。扩散的对应分裂不是 prefill/decode，而是“去噪前向”与“VAE 解码”两个阶段——前者是重计算的一致性函数调用（尤其多步档要循环多次），后者是相对轻计算但显存与带宽敏感的卷积式解码。把这两个阶段放在同一张卡上，解码的显存峰值会限制去噪批的大小；分离到不同卡或不同进程，去噪卡可以跑满大批，解码卡按自己的节奏消费潜空间结果，两边的批大小解耦。</p>\n<p>分离的传输代价是潜空间张量：每个请求的潜空间结果要跨卡搬运，尺寸远小于像素级输出，带宽压力可控，但引入了额外的同步点与队列。公式上，分离后的端到端延迟近似为 <span class=\"formula\">$$L = L_{\\text{denoise}}(B_d) + L_{\\text{xfer}} + L_{\\text{decode}}(B_v) + L_{\\text{queue}}$$</span>，其中队列项来自两池速率不匹配——去噪池产出快于解码池消费时，潜空间结果在中间队列堆积，尾延迟由队列深度决定。工程判断是让解码池的批大小略大于去噪池的产出速率对应的批，使得队列稳定在浅水位，而不是让解码池满负荷运转导致队列振荡。</p>\n<p>具体例子：一步档请求在去噪池以大批一次前向产出潜空间结果，解码池以中等批分块解码并直接返回；多步档请求则在去噪池占用较小批跑网格，网格结束后把终点潜空间交给解码池。分离的好处是多步档不再被解码显存挤压，坏处是一步档的低延迟路径多了一次跨池传输与排队，单请求延迟增加。是否值得分离取决于负载构成：一步档占比高且 SLO 紧时，同卡流水更优；多步档占比高且质量优先时，分离更优。这个判断不需要实验数字就能做出，因为两边的显存约束方向是明确的。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-29\">二十九 · 尾延迟怎么压：批成形的等待策略与回退路由</h3>\n<p>尾延迟的主要来源不是单请求计算，而是批成形时的等待与失败重试。一步档的批成形有一个天然的等待窗口：为了凑大批判摊解码开销，调度器会等一小段时间收集请求，这段等待直接加到每个已到请求的延迟上。压尾延迟的做法是给等待窗口设上限，并且让窗口随队列深度自适应——队列浅时窗口短（宁可小批快发），队列深时窗口长（大批摊薄）。这与 LLM 连续批处理的“不等”哲学相反，因为扩散一步档没有逐步插入的机会，等待是批成形的必要成本，只能被限制而不能被消除。</p>\n<p>第二个来源是失败重试。显存溢出、网格失配、解码超时都会触发整批失败，重试把尾延迟放大数倍。对策是把失败局部化：解码分块使解码失败只影响单块，网格分段使网格失败只影响单段，批成形时按显存档位截断使溢出在准入阶段就被拒绝而不是在计算中爆掉。监控指标要记录每档的批大小分布、显存峰值、解码耗时、超时率与回退比例，其中回退比例是关键——一步档在复杂条件上细节不足时回退多步档，回退本身是一次重新排队，若回退率高则说明一步档的准入条件（提示复杂度、分辨率）设得太宽，需要在前端做路由而不是在服务端做补救。</p>\n<p>第三个来源是 CFG 合并带来的批内样本数翻倍。把无条件与有条件样本拼成同一批一次前向，显存约为双分支的两倍批激活，批容量被砍半，批成形更难凑大，等待窗口被迫拉长。替代方案是串行两次前向（先无条件再有条件）以换取更大批容量，代价是两次前向的延迟叠加。取舍取决于 SLO 是延迟优先还是吞吐优先：延迟优先时合并批、接受小批；吞吐优先时串行、接受单请求延迟翻倍但批更大。这个取舍在调度层是可配置的，不需要改模型。</p>\n<p>最后落在具体机制上：调度器的准入控制应当以“显存配额 + 段长约束 + 回退预算”三元组为判据，而不是以最大批为判据。显存配额决定一步档与多步档各自的批上限，段长约束决定多步档的最坏等待，回退预算决定一步档允许多少请求走低质量路径。三者任一越界就触发排队或路由调整，而不是让整批在计算中失败。这套判据的代价是调度器需要维护每档的实时显存水位与段进度，收益是尾延迟从“由最坏批决定”变成“由配额与段长决定”，后者是可以在容量规划阶段算出来的。</p>\n<h3 id=\"paper-consistency-models-2023-sec-30\">三十 · 并行拓扑：一步档与多步档对切分维度的不同偏好</h3>\n<p>一致性模型把采样循环压成一次或数次前向，这直接改变了并行切分的成本结构。多步扩散的每一步都是一次完整的 U-Net/DiT 前向，步与步之间是严格串行的数据依赖，因此张量并行（TP）的 All-Reduce 会在每个去噪步重复发生，通信次数正比于步数；而一步档只有一次前向，同样的 TP 组内 All-Reduce 只发生一次，通信开销被摊薄到几乎可以忽略。这意味着：在多步档上不划算的 TP 宽度，在一步档上可能变得划算。工程判断是——按步数档位分别设定 TP 度，而不是全服务统一一个拓扑。</p>\n<p>四条切分轴在一致性模型服务中的角色各不相同。数据并行（DP）复制完整模型、切分请求批，是一步档扩容吞吐的首选，因为一步档单请求延迟已经很低，瓶颈转移到并发批的显存占用与 VAE 解码吞吐；流水并行（PP）把前向按层切到多卡，引入流水气泡，对单次前向的一步档几乎必然亏本，只在高分辨率、大骨干、单卡放不下时才考虑；专家并行（EP）只对 MoE 化的 DiT 骨干有意义，路由带来的 All-to-All 是另一类通信形态；张量并行（TP）切分单层内的矩阵乘，是降低单请求延迟的手段，代价是每层两次 All-Reduce。</p>\n<p>把通信量写成可估算的形式，设隐藏维为 <span>h</span>、批内 token 数为 <span>B</span>、精度字节数为 <span>b</span>、TP 度为 <span>N</span>，单层一次 All-Reduce 的环形通信量为：</p>\n<div class=\"formula\">$$V_{\\text{AR}} \\approx 2\\cdot\\frac{N-1}{N}\\cdot B\\cdot h\\cdot b$$</div>\n<p>乘以层数 <span>L</span> 与每请求前向次数 <span>S</span>（一步档 <span>S=1</span>，多步档 <span>S</span> 为步数），得到每请求的 TP 通信总量 <span>\\(V_{\\text{req}} \\approx S\\cdot L\\cdot V_{\\text{AR}}\\)</span>。这个式子给出两个直接结论：其一，多步档的通信量随步数线性放大，TP 度提高带来的延迟收益会被通信吃掉；其二，增大批 <span>B</span> 会同时放大计算与通信，但计算是 <span>O(B)</span> 的矩阵乘、通信是 <span>O(B)</span> 的线性搬运，二者比值不变，所以 TP 的性价比不随批增大而改善，只随单卡算力/带宽比改善。具体例子：一个 1024 隐藏维、24 层的 DiT 骨干，在 8 卡 NVLink 域内做 TP=8，一步档每请求的 All-Reduce 量级是单层几十 MB 乘层数，落在 NVLink 5 的高带宽区间内；同样的拓扑放到 8 步档，通信总量翻八倍，若单步计算未能充分掩盖，端到端延迟就会被通信主导。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-31\">三十一 · NVLink 5 与 NVSwitch：域内通信的带宽账本</h3>\n<p>Blackwell 世代的 NVLink 5 与 NVSwitch 把单 GPU 的域内互联带宽推到远高于 PCIe 的水平，GB200/GB300 NVL72 把 72 个 GPU 放进同一个 NVLink 域。对一致性模型而言，这个域的意义在于：TP 与 EP 的集合通信可以留在域内完成，不必跨节点走 InfiniBand。域内 All-Reduce 的可用带宽决定了 TP 度的实际上限——当 <span>\\(V_{\\text{req}}\\)</span> 除以有效带宽得到的通信时间接近单次前向的计算时间时，再加 TP 度就是负收益。</p>\n<p>判断通信是否成为瓶颈，用重叠率而不是绝对时间更稳。设单步计算时间为 <span>\\(T_{\\text{comp}}\\)</span>、单步通信时间为 <span>\\(T_{\\text{comm}}\\)</span>，若 <span>\\(T_{\\text{comm}} &lt; T_{\\text{comp}}\\)</span> 且 kernel 能与通信流重叠，则通信被隐藏；若 <span>\\(T_{\\text{comm}} \\gtrsim T_{\\text{comp}}\\)</span>，则每层都要等通信，TP 的加速比饱和。对一步档，<span>\\(T_{\\text{comp}}\\)</span> 是一次完整前向，量级大，重叠窗口充足；对多步档，每步的 <span>\\(T_{\\text{comp}}\\)</span> 相同但通信重复 <span>S</span> 次，重叠窗口被切碎，kernel 启动与同步开销上升。这就是为什么多步档更倾向用较小 TP、较大 DP 的拓扑：把并行度放到请求维度，让每张卡独立跑完整前向，域内通信只剩梯度无关的激活搬运（实际推理中为零）。</p>\n<p>代价面要算清楚：TP 度提高会降低单卡显存占用（权重与激活按层切分），但增加每卡持有的通信缓冲与同步等待；DP 度提高不降低单卡显存，只提高总吞吐，显存约束不变。因此显存受限时先动 TP/PP，吞吐受限时先动 DP。功耗侧，NVLink 域内高带宽交换的功耗随活跃链路数上升，NVL72 机柜级的功耗预算要按峰值通信配置留余量，不能按平均利用率估。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-32\">三十二 · All-to-All 与 EP：MoE 骨干的通信形态</h3>\n<p>若一致性函数的骨干是 MoE 化的 DiT，EP 会把专家分散到多卡，每个 token 经路由后被发送到持有目标专家的卡上，形成 All-to-All。与 All-Reduce 的对称环形不同，All-to-All 的通信量取决于路由分布的偏斜程度：热门专家收到的 token 多，对应链路的负载高，最慢链路决定整体时延。设 token 数为 <span>B</span>、每 token 选 <span>k</span> 个专家、隐藏维 <span>h</span>、字节 <span>b</span>，则 All-to-All 的总发送量约为：</p>\n<div class=\"formula\">$$V_{\\text{A2A}} \\approx 2\\cdot B\\cdot k\\cdot h\\cdot b$$</div>\n<p>系数 2 对应发送与回收两趟。这个量在多步档同样乘 <span>S</span>。工程上的关键不是算总量，而是算最热链路的负载：路由若集中在少数专家，即便总量不大，单链路也会成为瓶颈。缓解手段是容量因子与 token 丢弃/重排，但这会改变输出分布，对一步档的细节质量有直接影响——一致性模型的一步档本就依赖单次前向的完整性，丢弃 token 等于在唯一一次机会里损失信息，因此 EP 在一步档上要慎用，或把 EP 度压到路由能均衡的范围内。</p>\n<p>具体例子：一个 8 卡 EP 组，每卡 8 个专家，批内 4096 个 token、每 token 选 2 个专家、隐藏维 2048、FP8 一字节，则单趟发送量在数十 MB 量级，两趟翻倍；若路由偏斜使某卡承担三倍平均负载，该链路时间按三倍算。此时若单步计算时间不足以覆盖这条最热链路，EP 就成为端到端延迟的主导项。判断标准是：把最热链路的字节数除以该链路的有效带宽，与单步计算时间比较，前者更大就必须降低 EP 度或改路由策略。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-33\">三十三 · NIXL 传输：分离式部署下的数据面</h3>\n<p>一致性模型的服务化常采用预填/解码分离或编码/生成分离的形态：文本编码器、一致性函数骨干、VAE 解码器可能落在不同 GPU 甚至不同节点上，中间张量（条件嵌入、潜空间样本）需要在阶段之间搬运。NIXL 提供的是点对点、可绕过主机内存的传输抽象，让这类阶段间搬运不经过 CPU 中转。对一步档，端到端延迟由单次前向与 VAE 解码主导，阶段间搬运若走主机内存，会在关键路径上插入一次不可忽视的拷贝与同步；用 NIXL 直传可以把这段从关键路径上削掉。</p>\n<p>搬运量可以估：条件嵌入为 <span>\\(B\\cdot d_c\\cdot b\\)</span>，潜空间样本为 <span>\\(B\\cdot C\\cdot H\\cdot W\\cdot b\\)</span>（<span>C</span> 为潜通道数，<span>H,W</span> 为潜空间尺寸）。后者通常远大于前者，是阶段间传输的主要项。设有效传输带宽为 <span>BW</span>，则搬运时间为 <span>\\(T_{\\text{xfer}} = V_{\\text{latent}}/BW\\)</span>。对一步档，这个时间直接加在单请求延迟上，必须与单次前向时间同量级或更小；对多步档，潜空间样本只在最后一步产出一次，搬运不随步数放大，相对占比反而下降。这就是分离式部署在一步档上更敏感、在多步档上更宽容的原因。</p>\n<p>工程判断：把 VAE 解码放在与骨干同一 NVLink 域内，避免潜空间样本跨节点；跨节点只搬条件嵌入这类小张量。若必须跨节点搬潜空间样本，则要按 <span>\\(T_{\\text{xfer}}\\)</span> 与解码时间之和重算 SLO，并考虑在传输侧做量化压缩——但压缩会引入数值误差，对一步档的最终画质有直接风险，需在质量验证里单独评估。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-34\">三十四 · 通信何时成为瓶颈：三个可操作的判据</h3>\n<p>判据一，通信-计算比。对每个并行组，算 <span>\\(\\rho = T_{\\text{comm}}/T_{\\text{comp}}\\)</span>。一步档 <span>\\(\\rho\\)</span> 小，TP 可加宽；多步档 <span>\\(\\rho\\)</span> 随步数上升，TP 加宽的边际收益递减。当 <span>\\(\\rho\\)</span> 接近 1 时，继续加并行度只会把延迟从计算搬到通信，端到端不变甚至变差。</p>\n<p>判据二，批放大后的显存-带宽剪刀差。增大批 <span>B</span> 提升吞吐，但同时放大激活显存与通信量。显存先撞墙时，批不能再大，吞吐被显存锁死；通信先撞墙时，批再大也只是让每卡等更久。两个约束中先到者决定扩容方向：显存先到就加 DP 卡数分摊批，通信先到就减 TP 度、改拓扑。</p>\n<p>判据三，步数档位的路由比例。服务端按 SLO 把请求分到一步档与多步档，两档共享同一批 GPU 时，拓扑只能取一个。若回退多步档的比例上升，原本为一步档优化的宽 TP 拓扑会开始亏；监控回退比例与每档的通信等待时间，是把拓扑决策从静态配置变成动态判断的依据。失败模式很具体：按最大批统一调度、按一步档统一拓扑，结果多步档请求进来时显存溢出或通信等待把 SLO 打穿。</p>\n<table class=\"mini\"><thead><tr><th>切分轴</th><th>主要通信</th><th>一步档适用性</th><th>多步档适用性</th><th>主要代价</th></tr></thead><tbody><tr><td>DP</td><td>无（推理）</td><td>首选，扩吞吐</td><td>首选，扩吞吐</td><td>不降单卡显存</td></tr><tr><td>TP</td><td>每层 All-Reduce</td><td>可加宽，通信摊薄</td><td>慎用，通信乘步数</td><td>同步等待、缓冲显存</td></tr><tr><td>PP</td><td>阶段间激活</td><td>气泡亏本</td><td>仅大骨干放不下时</td><td>流水气泡</td></tr><tr><td>EP</td><td>All-to-All</td><td>慎用，丢 token 伤细节</td><td>需均衡路由</td><td>最热链路决定时延</td></tr></tbody></table>\n<p>把三个判据落到一个具体动作上：对一步档，拓扑取「宽 DP + 适度 TP + 同域 VAE 解码 + NIXL 直传小张量」；对多步档，拓扑取「宽 DP + 窄 TP + 批内共享时间网格减少 kernel 启动」。两档若必须共用硬件，则按回退比例设一个 TP 度的折中值，并把通信等待时间纳入每档的监控指标，与显存峰值、解码耗时、超时率并列。通信是否成为瓶颈，最终不是看带宽数字，而是看最慢那条链路的时间是否已经和单次前向的计算时间同量级——到了这个点，再加并行度就是白费。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-35\">三十五 · 并行切分下的一致性采样：通信何时吃掉少步收益</h3>\n<p>一致性模型的部署收益来自“前向次数少”，但这只压缩了计算维度，没有压缩通信维度。TP 切分把每层权重与激活按列/行拆分，每层后接一次 All-Reduce；EP 把条件嵌入与专家分支分散到不同 rank，需 All-to-All 交换 token；PP 把 U-Net/DiT 的层段切开，stage 间只传激活，但存在流水气泡；DP 复制权重、只同步梯度（推理时几乎无集合通信）。对一步档而言，端到端延迟 ≈ 单次前向计算 + 集合通信 + VAE 解码，当步数从数十步压到一步，通信在总延迟中的占比被结构性放大：多步档里每步通信可被后续计算掩盖，一步档没有后续计算可掩盖，All-Reduce 的固定开销直接暴露在关键路径上。用带宽-计算比判断边界：设单层计算量 $C$、单层需交换激活量 $B$、互联有效带宽 $\\beta$，则通信可被掩盖的条件近似为</p>\n<div class=\"formula\">$$\\frac{B}{\\beta}\\ \\le\\ \\frac{C}{F},\\qquad F=\\text{单卡有效算力}$$</div>\n<p>即 $B/C \\le \\beta/F$。NVLink 5 与 NVSwitch 抬高 $\\beta$，使 TP 在单机 NVL72 域内仍划算；跨节点走 InfiniBand 时 $\\beta$ 下降一个量级，同一 TP 度数的 All-Reduce 立刻从被掩盖变为瓶颈。工程判断是：一步档把 TP 限制在单 NVLink 域内，跨节点只做 DP 或 PP；多步档可容忍更高 TP 度数，因为每步通信能被下一步计算重叠。具体例子：一个 DiT 骨干在 8 卡 TP 下每层一次 All-Reduce，一步档的关键路径是“层数 ×（层计算 + All-Reduce）”，若把 TP 从 8 降到 4、改用 2 路 DP 复制，单请求延迟下降而吞吐由复制换回；这是用显存换延迟的典型取舍。</p>\n<p>EP 与 CFG 批合并叠加时通信代价更隐蔽。条件生成把无条件与有条件样本拼成同一批一次前向，显存约为双分支的两倍批激活；若同时按 EP 切分条件分支，All-to-All 的 token 量随批大小线性增长，而一步档不允许用“多步摊销”稀释这笔开销。All-to-All 的代价可写成</p>\n<div class=\"formula\">$$T_{\\mathrm{A2A}}\\ \\approx\\ \\frac{2\\,(N-1)}{N}\\cdot\\frac{S}{\\beta_{\\mathrm{link}}}+\\tau_{\\mathrm{launch}}$$</div>\n<p>其中 $S$ 为每 rank 发送字节、$N$ 为 EP 组大小、$\\tau_{\\mathrm{launch}}$ 为 kernel 启动与同步开销；$N$ 增大时带宽项趋饱和，但 $\\tau_{\\mathrm{launch}}$ 与跨节点跳数上升。因此 EP 组应尽量落在同一 NVSwitch 域，跨域 EP 只对多步档有意义。NIXL 传输用于分离式预填/解码或跨节点激活搬运：它把传输从集合通信中解耦，适合把 VAE 解码或后处理放到独立资源池，但引入一次显式传输延迟，一步档下这笔延迟无法被计算掩盖，需与解码耗时一起计入 SLO 预算。</p>\n<table class=\"mini\"><thead><tr><th>并行维度</th><th>一步档适用性</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>TP（单 NVLink 域）</td><td>可用，度数受限</td><td>每层 All-Reduce 暴露在关键路径</td><td>跨节点 TP 使带宽项超过计算项</td></tr><tr><td>EP</td><td>谨慎，组内同域</td><td>All-to-All 随批线性增长</td><td>CFG 批合并后 token 量翻倍</td></tr><tr><td>PP</td><td>可用，气泡占比高</td><td>stage 间激活传输与流水气泡</td><td>stage 数多、单批小，气泡无法填满</td></tr><tr><td>DP</td><td>首选扩容方式</td><td>权重复制占显存</td><td>显存档位不足，复制挤占批激活</td></tr></tbody></table>\n<p>调度侧必须把通信代价写进分档逻辑，而不是按最大批统一调度。一步档的批大小受两倍 CFG 激活与 TP 通信共同约束：增大批提升吞吐但拉长 All-Reduce 消息，延迟分位数恶化；多步档可用较大 TP 与 EP 摊薄通信，但需减小批控制中间激活峰值。监控应记录每档的集合通信耗时占比、All-to-All 字节量、跨节点流量与回退多步档比例；当通信占比超过单次前向计算耗时的一半，说明该拓扑已不适合一步档，应降 TP 度数或改为 DP 复制。VAE 解码若走 NIXL 搬到独立池，需把传输与解码串行时间计入超时判定，避免一步档名义上“一次前向”却在传输环节违约。</p>\n<h3 id=\"paper-consistency-models-2023-sec-36\">三十六 · 精度塌陷：一步档的“看起来对、其实不对”</h3>\n<p>一致性模型在部署侧最危险的失败不是崩溃，而是输出“还能看”但已经偏离。一步档把 <span class=\"inline\">x_T</span> 直接映射到 <span class=\"inline\">x_ε</span>，路径上没有迭代求解器做误差累积与自我修正，任何数值偏差都被单次前向一次性放大到终点。精度塌陷有三条典型来源：其一是时间步嵌入的数值精度，若把时间步 <span class=\"inline\">t</span> 以低精度传入骨干，时间嵌入的高频分量被截断，模型对“当前处于轨迹哪个位置”的判断变模糊；其二是权重与激活量化，FP8/NVFP4 在一步档上缺少多步路径的误差平均效应，量化噪声直接进入终点预测；其三是 CFG 批合并后条件与无条件样本共享同一 kernel，若引导尺度较大，无条件分支的偏差会通过批内归一化类算子串扰到有条件样本。</p>\n<p>诊断上不能只看端到端图像指标，要把一致性函数本身当作被测对象：对同一 <span class=\"inline\">x_t</span> 分别用高精度参考路径与部署路径求 <span class=\"inline\">f(x_t,t)</span>，比较两者在潜空间的相对误差，而不是比较解码后的像素。定义部署路径与参考路径的终点偏差</p>\n<div class=\"formula\">$$\\delta(t)=\\frac{\\big\\| f_{\\text{deploy}}(x_t,t)-f_{\\text{ref}}(x_t,t)\\big\\|_2}{\\big\\| f_{\\text{ref}}(x_t,t)\\big\\|_2}$$</div>\n<p>在时间网格上扫 <span class=\"inline\">t</span> 得到 <span class=\"inline\">\\(\\delta(t)\\)</span> 曲线，若曲线在 <span class=\"inline\">t</span> 接近 <span class=\"inline\">T</span>（纯噪声端）时陡升，说明时间嵌入或先验噪声处理有问题；若在 <span class=\"inline\">t</span> 接近 <span class=\"inline\">\\(\\epsilon\\)</span> 时抬升，说明终点附近的细节预测被量化吃掉。这条曲线的代价很低：只需固定一批 <span class=\"inline\">x_t</span> 做两次前向，显存开销等于一个推理批，不引入额外延迟到线上路径。工程判断是：把 <span class=\"inline\">\\(\\delta(t)\\)</span> 的最大值作为一步档的准入闸门，超过阈值即把该请求路由到多步档，而不是等用户投诉细节丢失。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-37\">三十七 · OOM：中间激活而非 KV 才是主约束</h3>\n<p>图像生成主路径没有自回归 KV cache，容量约束落在中间激活与 VAE 解码上。一致性函数单次前向的激活峰值与批大小近似线性，但有两个非线性放大项：CFG 批合并使有效批翻倍，显存约为双分支的两倍批激活；多步档在时间网格上循环，若实现里保留了每步的计算图或缓存了重新加噪的中间张量，峰值会随步数叠加而不是持平。OOM 往往不在稳态出现，而在“一步档大批 + 突发 CFG 请求”叠加时出现，因为调度器按平均显存做容量规划，忽略了 CFG 请求的翻倍效应。</p>\n<p>定位手段是把显存峰值按阶段打点：编码（条件嵌入）、一致性函数前向、重新加噪、VAE 解码四段分别记录峰值，而不是只记端到端峰值。伪代码思路是给每个阶段包一层显存采样钩子，在批维度上做二分搜索找该阶段的可行批上限：</p>\n<div class=\"formula\">$$B_{\\max}^{(s)}=\\max\\{B:\\ \\text{peak}^{(s)}(B)\\le M_{\\text{budget}}-\\text{reserve}\\}$$</div>\n<p>其中 <span class=\"inline\">s</span> 为阶段，<span class=\"inline\">\\(M_{\\text{budget}}\\)</span> 为该档位的显存预算，reserve 留给碎片与解码临时缓冲。工程代价是二分搜索要跑若干次前向，但只需在模型版本上线或精度方案变更时做一次标定，把 <span class=\"inline\">\\(B_{\\max}^{(s)}\\)</span> 写进调度器的档位表。具体例子：一步档标定出 <span class=\"inline\">\\(B_{\\max}\\)</span> 后，CFG 请求按“有条件样本数”折算批大小，即批内拼入等量无条件样本时把有条件样本数减半，避免合并后越界。回滚策略是显存超限时先降 CFG 合并（退回双分支顺序执行，显存降但延迟升），再降批，最后降步数档位，顺序不能反，因为降步数直接损伤质量。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-38\">三十八 · 批抖动：步数分档下的吞吐震荡</h3>\n<p>批抖动指同一档位内批大小在相邻调度周期之间大幅跳变，导致 kernel 启动开销与显存分配器反复扩张收缩。根因是请求到达的步数档位混合：一步档请求短、到达密集，多步档请求长、占用显存高，若调度器用单一队列按 FIFO 组批，会在一步档请求堆积时把批撑大，随后多步档请求进入又被迫切小批，形成锯齿。抖动本身不直接违约，但它把尾延迟推高，因为大批的 VAE 解码与重新加噪阶段被拉长，排在其后的短请求等待时间不可控。</p>\n<p>机制上按步数分档建独立队列，每档独立组批、独立标定批上限，档间不共享批。组批窗口用时间片而非固定批大小：在窗口内尽量填批，窗口结束即发车，窗口长度按该档 SLO 的尾延迟预算反推。吞吐与尾延迟的权衡可写成</p>\n<div class=\"formula\">$$\\text{throughput}\\approx\\frac{B\\cdot N_{\\text{req}}}{T_{\\text{forward}}(B)+T_{\\text{decode}}(B)},\\qquad \\text{tail}\\propto W_{\\text{batch}}+T_{\\text{forward}}(B)$$</div>\n<p>其中 <span class=\"inline\">\\(W_{\\text{batch}}\\)</span> 为组批窗口。窗口拉长提升吞吐但直接加到尾延迟上，所以一步档窗口应短、批上限可高；多步档窗口可略长以摊薄每步 kernel 启动，但批上限必须压低以控激活峰值。具体例子：把一步档与多步档混在同一队列时，监控会看到批大小序列呈锯齿、超时率随到达率波动；拆成两档后批大小序列平稳，尾延迟分位数收敛。诊断批抖动看两个指标：批大小的相邻周期变异系数，以及显存分配器的扩张次数；后者上升说明抖动已触发分配器重分配，属于要立即拆档的信号。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-39\">三十九 · 尾延迟：回退路径的隐藏成本</h3>\n<p>一步档的尾延迟不由平均前向时间决定，而由回退比例决定。复杂条件或高分辨率请求在一步档上细节不足，服务端保留回退多步档的路由，回退请求要重新走多步循环，端到端延迟是“一次失败的一步前向 + 多步循环”之和，比直接走多步档更贵。若回退判定放在解码之后（看图像质量再决定），成本还要加上一次 VAE 解码。尾延迟监控必须把回退请求单独打标，否则它们混在一步档的延迟分布里，把 p99 拉高却看不出原因。</p>\n<p>定位方法是按请求打三段计时：排队等待、一步档前向加解码、回退追加的多步循环，分别记分位数。回退比例本身是核心指标，它同时反映一步档质量与路由阈值是否过松。工程判断是把回退判定前移到潜空间：用第一节的 <span class=\"inline\">\\(\\delta(t)\\)</span> 或条件嵌入的置信度做闸门，在 VAE 解码前决定是否回退，省掉一次解码。代价是闸门本身要一次额外前向或轻量判别器，显存开销小但增加固定延迟；收益是回退请求不再付解码的冤枉钱。具体例子：高分辨率请求在一步档上回退比例偏高时，正确动作不是调松闸门硬扛，而是把该分辨率段整体路由到多步档，让一步档只服务它擅长的段位。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-40\">四十 · 静默降级：没有报错的质量滑坡</h3>\n<p>静默降级是最难监控的一类：服务不报错、延迟正常、显存正常，但输出质量在某个版本或某个负载区间悄悄下滑。一致性模型的静默降级有三个高发点。第一是时间网格失配：多步档在时间网格上交替去噪与重新加噪，若网格点与训练时的时间步采样分布不一致，质量下降但不触发任何异常，因为每步前向都“成功”了。第二是 EMA 目标网络与部署权重的错配：蒸馏产物若误用了训练中间检查点而非收敛后的学生权重，一致性损失在离线看正常，线上一步档细节偏软。第三是精度方案变更：把权重切到 FP8/NVFP4 后吞吐上升，一步档在简单条件上看不出差异，复杂条件上细节退化被平均指标掩盖。</p>\n<p>监控上要建立与线上流量同分布的固定探针集，按条件复杂度分层（简单提示、复杂提示、高分辨率），每层记录潜空间终点偏差与解码后的一致性指标，按版本与精度方案打标对比。探针集不追求覆盖全部请求，只求分层可复现，每次模型或精度变更前后各跑一次，偏差抬升超过阈值即阻断发布。代价是探针推理占用少量显存与算力，放在低峰期跑；收益是把静默降级从“用户发现”变成“发布前发现”。具体例子：多步档网格失配的典型信号是“步数增加但质量不升反降”，探针集上表现为多步档指标低于一步档，这个反常组合应直接触发网格配置回滚，而不是继续调步数。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-41\">四十一 · 回滚：按档位而非按整机</h3>\n<p>回滚粒度决定故障恢复速度。把一步档与多步档、不同精度方案、不同批上限绑成一次整机发布，任何一处失败都要整机回退，恢复时间长且把未受影响的档位一起拖下水。正确做法是按档位与精度方案做配置化发布：步数档位、批上限、CFG 合并开关、精度方案各自独立版本化，回滚只动出问题的那一维。回滚触发条件要写成可执行的判据，而不是“质量变差”这种描述：一步档回退比例超过基线、探针集分层偏差抬升、尾延迟分位数越界、显存分配器扩张次数异常，任一触发即回滚对应维度。</p>\n<p>机制上维护一张档位配置表，每行是一个可独立回滚的维度，线上请求按路由键查表。回滚动作是改表项并让新请求生效，在途请求按旧配置跑完，避免中途切换造成批内不一致。代价是配置表要多一层版本管理与灰度，收益是单维回滚的恢复时间从整机重启级降到配置生效级。具体例子：精度方案从高精度切到 FP8 后一步档探针偏差抬升，回滚只把精度维度切回，步数档位与批上限不动，吞吐损失局限在一步档而多步档继续按原方案服务。最后落在工程判断上：一致性模型的失败模式大多不崩溃，监控体系的重心应放在分层探针与潜空间偏差上，把回退比例、批大小变异系数、显存分配器扩张次数作为三个常驻告警项，比盯端到端延迟更能提前发现精度塌陷与静默降级。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-42\">四十二 · 失败模式与诊断：精度塌陷、OOM、批抖动、尾延迟、静默降级</h3>\n<p>一致性模型部署最危险的失效不是崩溃，而是<strong>静默降级</strong>：一步档仍按时返回、HTTP 200、无异常日志，但复杂条件与高分辨率下的细节已退化。根因在一致性函数的映射假设——它把同一概率流 ODE 轨迹上任意 (x_t,t) 映射到同一终点 x_ε，一步档等于假设先验噪声 x_T 与目标终点落在同一轨迹上。条件嵌入一旦偏离训练分布，该假设松动，输出退化为“平均脸”式模糊。诊断不能靠单张目检，需在服务侧埋一个轻量判别器或对回退多步档的输出做分布距离比对，把“一步档输出与多步档输出的感知距离”作为在线指标；该指标越界即触发回退路由。代价是每请求多一次多步档前向用于比对，吞吐下降，故只对抽样比例请求执行。</p>\n<p>第二类失效是<strong>时间网格失配</strong>。多步档在时间网格上交替去噪与重新加噪，循环次数即步数；若服务端为省延迟私自压缩网格（例如把训练分布外的粗网格塞进调度），一致性损失约束的相邻时刻自洽性被破坏，质量下降却不报错。定位手段是记录每档实际时间步序列与训练侧采样分布的偏移量，用下式做在线告警：</p>\n<div class=\"formula\">$$\\mathrm{drift}=\\max_{k}\\ \\big|\\,\\tau_k-\\hat{\\tau}_k\\,\\big|\\ \\big/\\ \\Delta t_{\\text{train}}$$</div>\n<p>其中 τ_k 为运行时第 k 步时刻、τ̂_k 为训练分布最近邻时刻。drift 超阈值即判定网格被篡改，回滚到标准网格。代价是多步档延迟回升，属可接受的 SLO 折中。</p>\n<p>第三类是<strong>批抖动与 OOM 的耦合</strong>。一步档可增大批提升吞吐，多步档需减小批控制中间激活峰值；若调度器按最大批统一调度，多步档请求会把激活峰值推过显存上限。CFG 批合并更危险：无条件与有条件样本拼成同一批一次前向，显存约为双分支的两倍批激活，批大小翻倍而显存预算未同步调整时直接 OOM。诊断应把显存峰值与批大小、步数档位、是否 CFG 合并做成四元组埋点，OOM 前兆是峰值逼近上限的持续爬升而非瞬时尖峰。回滚策略是分档独立批上限，CFG 合并请求单独走小批队列。</p>\n<table class=\"mini\"><thead><tr><th>失效</th><th>可观测信号</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度塌陷</td><td>一步/多步输出距离越界</td><td>抽样比对判别器</td><td>路由至多步档</td></tr><tr><td>网格失配</td><td>drift 超阈值</td><td>时间步序列埋点</td><td>恢复标准网格</td></tr><tr><td>OOM</td><td>显存峰值持续爬升</td><td>批/档/CFG 四元组</td><td>分档批上限</td></tr><tr><td>尾延迟</td><td>P99 超时率上升</td><td>VAE 解码耗时拆分</td><td>解码批降档</td></tr></tbody></table>\n<p>尾延迟的主因常不在一致性函数前向，而在 VAE 解码：解码批大小与精度方案影响端到端延迟，材料未给出具体解码耗时数字，但解码是输出阶段主要开销之一。把单请求延迟拆成“前向 + 解码 + 排队”三段后，P99 抬升若集中在解码段，说明解码批被大请求挤占，应把解码与采样解耦为独立队列。最后是<strong>EMA 目标滞后</strong>的隐性代价：训练侧 EMA 衰减率不当会造成目标网络滞后，蒸馏学生继承该偏差后表现为一步档系统性偏色或结构漂移，服务侧只能通过版本回滚隔离，故每次权重上线需绑定一步档与多步档的双档回归基线，任一档越界即整包回滚，不做单档热修。</p>\n<h3 id=\"paper-consistency-models-2023-sec-43\">四十三 · 基准口径的三层结构：模型态、服务态、硬件态</h3>\n<p>读一致性模型的推理数字，第一件事是把“模型态”与“服务态”分开。模型态指论文卡上的一句话：一致性函数 <span>f_θ(x_t,t)</span> 单次前向直接输出轨迹终点 <span>x_ε</span>，推理路径不含迭代 ODE 求解器。服务态则是这条路径落到队列里之后的样子：一步档的单次前向、多步档在时间网格上的循环、CFG 批合并后的批内样本翻倍、VAE 解码的批大小与精度。两者之间隔着调度器、批构造与显存档位，任何跨过这条边界的对比都必须显式标注。硬件态是第三层：B200/B300 单卡、GB200/GB300 NVL72 机柜内的单节点、跨节点，三种拓扑下同一份权重的显存占用与通信代价完全不同。材料未给出部署硬件档位与并行拓扑，因此本卷不给出任何跨档位的绝对延迟数字，只给出口径规则：报告一步档延迟时必须同时写明批大小、分辨率、VAE 解码是否计入、是否启用 CFG 批合并；缺任一项，该数字不可与他人的数字并列。</p>\n<p>口径失配最典型的来源是步数定义。一步档的“一步”是一次前向；多步档的“N 步”是 N 次一致性函数调用，每次调用后还要按调度重新加噪，重新加噪本身是访存操作而非计算。因此多步档的端到端延迟近似为：</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx N\\cdot\\big(t_{\\text{fwd}}(B)+t_{\\text{renoise}}(B)\\big)+t_{\\text{VAE}}(B)+t_{\\text{queue}}$$</div>\n<p>其中 <span>B</span> 是批大小，<span>t_renoise</span> 随批线性增长但远小于前向，<span>t_queue</span> 是排队时间。把 N 步的延迟除以 N 再与一步档比较，是常见的错误归一化——它把重新加噪与队列开销摊薄掉了，得出“多步档单步更便宜”的假象。正确做法是报告端到端延迟与步数两个独立量，让读者自己看折中点。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-44\">四十四 · 批与并发的耦合：一步档与多步档不是同一个容量问题</h3>\n<p>一步档的显存峰值由三块构成：权重、单次前向的中间激活、VAE 解码的批激活。多步档在同一批上循环，中间激活在每步被复用而非累积，因此其显存峰值并不随步数线性增长——真正随步数增长的是时间，不是显存。这条性质决定了两档的容量曲线形状不同：一步档是显存受限，多步档是延迟受限。服务端若按最大批统一调度，会把多步档塞进一步档的批上限，结果是显存溢出或 SLO 违约；反之把一步档压到多步档的小批，则白白损失吞吐。</p>\n<p>CFG 批合并是这条曲线上最容易被误读的一环。把无条件与有条件样本拼成同一批一次前向，显存约为双分支的两倍批激活，但计算只走一次前向而非两次。于是“批大小”这个词在两种实现下含义不同：双分支实现里批大小 B 对应 2B 条样本的激活，合并实现里批大小 2B 才对应同样的样本数。跨实现比较吞吐时，必须把批大小换算到“每批样本数”这一口径，否则合并实现的吞吐会被系统性高估。容量规划上，设显存档位为 <span>M</span>，单样本激活为 <span>a</span>，权重与解码缓冲为 <span>c</span>，则合并实现的最大样本批为：</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor \\frac{M-c}{2a}\\right\\rfloor$$</div>\n<p>这个式子里的 2 来自 CFG 合并，不是来自步数。工程判断是：一步档优先吃满 <span>B_max</span> 换吞吐，多步档则要按 SLO 反推批大小，因为多步档的批越大，单请求排队等待越久，尾延迟分位数越难看。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-45\">四十五 · 指标读法：TTFT/TPOT 在扩散服务里的映射与陷阱</h3>\n<p>TTFT 与 TPOT 原本是自回归解码的指标，搬到扩散服务上需要重新定义，否则会产生不可比的数字。对一步档，TTFT 是请求入队到首字节返回的时间，包含排队、单次前向与 VAE 解码；TPOT 没有自然对应物，因为输出不是逐 token 生成的。硬套 TPOT 的做法是把 VAE 解码切成若干块逐块返回，此时 TPOT 度量的是解码分块节奏，与前向计算无关。对多步档，一个可用的映射是把每次一致性函数调用视为一个“步”，步间时间即 TPOT 的类比量，但必须注明它包含重新加噪。两种映射下的 TPOT 不可比。</p>\n<p>吞吐的口径同样分叉。图像生成的吞吐通常按“每秒完成请求数”计，但请求的分辨率、步数档位、是否 CFG 合并都会改变单请求的计算量。把不同分辨率与步数的请求混在一个吞吐数字里，等于把加权平均当成常数。可操作的做法是按档位分层报告：一步档吞吐、多步档各步数档吞吐、回退比例。回退比例是一致性模型特有的指标——一步档在复杂条件上细节不足时服务端回退多步档，回退比例上升意味着一步档的实际有效吞吐下降，即使其名义吞吐不变。监控指标应包含每档步数、批大小、显存峰值、解码耗时、超时率与回退比例，这六项构成一个自洽的口径闭环。</p>\n<p>功耗维度在 Blackwell 上不能忽略。NVL72 机柜内单节点功耗预算固定，一步档把计算压到单次前向，单位请求的能耗低于多步档，但批越大单次前向的瞬时功耗越高。功耗与吞吐的比值（每请求焦耳）才是跨档位可比的量，材料未给出具体功耗数字，因此只能定性：一步档在能耗口径上占优的前提是批足够大以摊薄静态功耗，否则小批一步档的每请求能耗可能高于大批多步档。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-46\">四十六 · 哪些提升不可比：四类常见的伪对比</h3>\n<p>第一类是把一步档与多步教师模型直接对比质量。一致性模型的蒸馏路径以预训练扩散模型为教师，学生复用教师参数初始化，一步档的输出是轨迹终点的单次估计，教师是多步 ODE 求解器的积分结果。两者的质量差异是方法定义的固有差异，不是实现优劣；把“一步档 FID 略高”读成“实现退步”是口径错误。材料未给出可核验的 FID 数字，因此本卷不排列任何质量名次，只要求报告时注明步数与是否蒸馏。</p>\n<p>第二类是把不同时间网格的多步档互比。多步一致性采样在时间网格上交替去噪与重新加噪，网格与训练分布失配会导致质量下降。两个实现若网格端点、步长分布、重新加噪调度不同，其 N 步结果不可比，即使 N 相同。第三类是把 CFG 合并实现与双分支实现的吞吐互比而不换算批口径，这在第二节已述。第四类是把不同硬件档位的延迟互比：单卡 B200 与 NVL72 机柜内的单节点，同一份权重的可用显存与通信拓扑不同，批上限不同，端到端延迟不可直接并列。四类伪对比的共同特征是省略了口径标注中的某一项，读者无法复原实验条件。</p>\n<p>还有一个隐蔽的不可比来源：训练阶段的超参未公开。时间步采样分布与损失权重 <span>λ(t)</span> 影响稳定性，EMA 衰减率影响目标网络滞后程度，蒸馏步数影响学生拟合的轨迹段长度。材料未给出这些取值，因此任何“我们的训练更稳”的声明都无法在论文卡层面复核。工程上应把这几项视为口径的一部分，报告时一并给出，否则跨实现的稳定性对比不成立。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-47\">四十七 · 可复现的最小报告模板与工程判断</h3>\n<p>给定材料的事实边界，一个可复现的报告模板应包含：硬件档位（单卡型号或机柜拓扑）、精度方案（材料未给出量化方案，推理侧可考虑 FP8/NVFP4 但需验证一步档质量）、步数档位与时间网格定义、批大小与 CFG 是否合并、分辨率、VAE 解码是否计入端到端、TTFT 与端到端延迟的分位数、吞吐按档位分层、显存峰值、回退比例与超时率。缺任何一项，该组数字只能作为定性参考。这个模板的代价是报告变长，收益是跨实现的数字终于可以并列。</p>\n<p>工程判断落在路由上。服务端按步数分档：一步档走低延迟队列并吃满批上限，多步档走吞吐队列并按 SLO 反推批大小；两档共享同一份权重但各自持有独立的批构造逻辑。回退路径必须显式存在且有监控，因为一步档在复杂条件上细节不足是方法定义的局限而非实现缺陷。容量规划时，把一步档的名义吞吐乘以（1 − 回退比例）才是有效吞吐，这个乘积才是与多步档吞吐可比的量。最后一条判断关于蒸馏：蒸馏质量受教师 ODE 求解器精度与轨迹点对构造方式影响，材料未给出定量边界，因此部署前必须在目标硬件档位上用固定提示集测一遍一步档与多步档的质量差，把差值写进路由阈值，而不是沿用论文卡上的定性描述。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-48\">四十八 · 基准口径：步数档位不可混读，显存与延迟要分账</h3>\n<p>一致性模型的基准读数必须先绑定步数档位，否则数字不可比。一步档的单请求延迟由一次一致性函数前向加一次 VAE 解码构成，不含迭代求解器，也没有 CFG 双分支串行合并；多步档在时间网格上循环“去噪—重新加噪”，延迟随循环次数近似线性增长，且每步都引入 kernel 启动与调度开销。因此把一步档的 TTFT/TPOT 与多步档的吞吐放在同一张表里对比，等于把不同计算图混为一谈。可比的口径应写成三元组（步数档、批大小、分辨率），并同时记录回退多步档的比例——回退比例升高会直接污染一步档的延迟分位数。</p>\n<p>显存侧要分两笔账。条件生成若把 CFG 的无条件与有条件样本拼成同一批一次前向，批激活约为双分支的两倍，批大小必须按显存档位截断；而多步档的中间激活峰值随循环保留，一步档则只驻留单次前向的激活与解码缓冲。可用一个粗略的容量判据约束调度：</p>\n<div class=\"formula\">$$B_{\\max}\\approx\\left\\lfloor \\frac{M_{\\mathrm{free}}-M_{\\mathrm{dec}}-M_{\\mathrm{w}}}{k\\cdot a_{\\mathrm{act}}(s,\\,r)}\\right\\rfloor$$</div>\n<p>其中 $M_{\\mathrm{free}}$ 为可用显存，$M_{\\mathrm{dec}}$ 为 VAE 解码缓冲，$M_{\\mathrm{w}}$ 为权重常驻，$a_{\\mathrm{act}}$ 为单样本激活，$k$ 为 CFG 合并倍数（未合并取 1），$s$ 为步数档、$r$ 为分辨率。一步档可放大 $B$ 换吞吐，多步档必须缩小 $B$ 压峰值，按最大批统一调度必然在某一档溢出或违约 SLO。</p>\n<table class=\"mini\"><thead><tr><th>读数项</th><th>可比条件</th><th>不可比情形</th></tr></thead><tbody><tr><td>单请求延迟</td><td>同步数档、同分辨率、同 CFG 合并方式</td><td>一步档对多步档直接比 P99</td></tr><tr><td>吞吐</td><td>同显存档位、同批上限、同回退率</td><td>一步档大批对多步档小批</td></tr><tr><td>显存峰值</td><td>同解码批与精度方案</td><td>忽略 VAE 解码缓冲只报模型权重</td></tr></tbody></table>\n<p>功耗与失效边界同样要单列。一步档把算力开销压到单次前向，功耗曲线更平，但复杂条件与高分辨率下细节不足，需保留回退路由并监控超时率；多步档的网格若与训练时的时间步采样分布失配，质量下降不会体现在延迟指标上，只会体现在回退率与人工抽检里。蒸馏路径的可比性还受教师 ODE 求解器精度约束：学生复用教师参数初始化，教师轨迹点对构造方式一变，少步质量边界就变，跨教师版本的吞吐提升不可直接相减。工程判断是：基准报告以步数档为主键，显存按激活与解码分账，任何跨档提升必须标注回退比例与网格配置，否则只能算定性结论。</p>\n<h3 id=\"paper-consistency-models-2023-sec-49\">四十九 · 迁移到非扩散生成范式：一致性约束的前提在不在</h3>\n<p>一致性模型的可迁移性不取决于骨干网络，而取决于一个前提：生成过程必须能被写成一条从先验到数据的确定性轨迹，且轨迹上任意点共享同一终点。概率流 ODE 满足这一点，所以 f(x,t) 的映射目标良定义。迁到自回归解码时，这个前提直接断裂——token 序列没有连续时间轴，也没有“同一轨迹相邻点”的概念，一致性损失无处落地。迁到扩散语言模型（离散扩散）时前提部分成立：状态空间是离散 token 单纯形，概率流 ODE 需换成离散时间马尔可夫链的转移核，相邻点对变成相邻掩码比例的两步状态，一致性函数输出的是终点 token 分布而非连续 x_ε，损失从 L2 改为对分布的距离（KL 或交叉熵）。工程代价在于：离散状态下 EMA 目标网络给出的目标是分布而非点，方差更大，时间步采样必须按掩码比例而非连续 t 均匀取，训练稳定性对 λ(t) 的依赖比连续情形更敏感。具体例子：把图像一致性模型直接套到 Flash-dLLM 那类并行解码路径上，若沿用 L2 损失对 logits 做回归，梯度会被 softmax 饱和吃掉，必须换损失函数，这不是调参而是改结构。</p>\n<p>判断标准可以写成一句可检验的话：若目标域的生成过程存在一个可数值积分的连续或半连续状态转移，且终点对轨迹上各点唯一，则一致性训练可迁；否则只能迁“蒸馏压缩步数”这一半，不能迁“自洽训练”这一半。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-50\">五十 · 换骨干与换分辨率：f(x,t) 的容量与感受野要重估</h3>\n<p>一致性函数把整条轨迹的信息压进单次前向，这意味着它的容量需求高于单步去噪网络。从 U-Net 迁到 DiT 时，时间步嵌入的注入方式从 FiLM 调制变为 adaLN-Zero 调制，一致性损失的梯度会更多地流向时间嵌入分支，若 adaLN 的零初始化门控过强，早期训练中 f 对 t 的敏感度不足，多步档在网格上的自洽性会退化。迁移时要做的具体改动是：放宽时间嵌入分支的初始化门控，并在 λ(t) 中对接近 ε 的时刻加权，因为终点附近的相邻点差异最小、信噪比最低。</p>\n<div class=\"formula\">$$\\lambda(t)\\propto\\frac{1}{\\sigma_t^2+\\kappa},\\quad \\text{使 }\\lambda(t)\\text{ 在 }t\\to\\epsilon\\text{ 时抬升，补偿终点邻域的低信噪比}$$</div>\n<p>分辨率迁移的代价更直接：一致性模型的单次前向要覆盖全图，高分辨率下注意力开销随 token 数平方增长，而一步档没有迭代分摊，全部算力压在一次前向里。这与多步扩散的算力分布完全不同——后者可以把高分辨率计算摊到几十步，前者必须一次性付清。工程判断：一步档在高分辨率下的可行域由单次前向的显存峰值与注意力 kernel 效率决定，而不是由步数决定；若目标分辨率使单次前向的激活超过显存档位，应优先降批而非降分辨率，因为降分辨率会改变训练分布、触发网格失配。具体例子：同一骨干从潜空间 64×64 迁到 128×128，token 数翻四倍，一步档的批大小需按激活峰值重算，多步档反而可以靠减小批维持，两条档位的容量曲线在分辨率轴上分叉。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-51\">五十一 · 蒸馏路径的迁移边界：教师精度决定学生上限</h3>\n<p>蒸馏阶段的可迁移性受教师 ODE 求解器精度约束。学生学的是教师轨迹上的相邻点对，若教师用低阶求解器（如一阶 Euler）生成点对，轨迹本身带有离散化误差，学生把误差一并学进去，一步档的输出会系统性偏离真实概率流终点。迁移到新领域时，教师往往换成了该领域的预训练扩散模型，其求解器配置、时间网格、CFG 尺度都是既定的，学生无法选择。可操作的判断是：先验证教师在目标域上的 ODE 轨迹自洽性——取同一初始噪声，用两种不同步数的求解器跑到同一终点，比较终点差异；差异大则说明教师轨迹本身不稳定，蒸馏出的学生一步档不可信，应退回多步档或改用更高阶求解器重建点对。</p>\n<p>代价体现在蒸馏的算力预算上：教师生成点对是离线或半离线过程，每个训练样本需要一次完整的多步求解，算力开销与教师步数线性相关。迁到视频或长序列领域时，教师单次求解的显存与时间成本放大，点对生成成为蒸馏管线的主要瓶颈，而非学生训练本身。这与 6Bit-Diffusion、CorGi 那类在推理侧做量化或缓存的方案形成互补关系：它们压缩的是教师或学生的单次前向成本，一致性蒸馏压缩的是步数，两者叠加时要注意量化误差会改变教师轨迹，点对需在量化后的教师上重新生成，否则学生学的是未量化轨迹。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-52\">五十二 · 规模上限：一步档的吞吐天花板在哪</h3>\n<p>一步档把延迟压到单次前向加 VAE 解码，吞吐上限随之从“采样循环”转移到“单次前向的算力效率”与“解码带宽”。设单次前向的算力为 C、解码的显存带宽需求为 B、批大小为 n，则端到端时间的下界近似为两者取大：</p>\n<div class=\"formula\">$$T_{\\text{step1}}(n)\\approx\\max\\left(\\frac{n\\cdot C_{\\text{fwd}}}{\\text{PeakFLOPS}\\cdot\\eta},\\ \\frac{n\\cdot S_{\\text{latent}}}{B_{\\text{HBM}}}\\right)+T_{\\text{overhead}}$$</div>\n<p>其中 η 是 kernel 效率，S_latent 是单样本潜空间到像素的输出字节数。这条式子给出规模上限的判据：当 n 增大到前向算力项与解码带宽项相等时，继续加批只增延迟不增吞吐，此时应转而优化解码（降精度、分块解码）或提高 kernel 效率，而不是继续堆批。多步档的上限则被中间激活显存卡住，批大小随步数增加而收缩，吞吐曲线在步数轴上单调下降。两条曲线的交点就是服务端分档路由的经济学依据：低于交点走一步档，高于交点走多步档。具体例子：条件生成时 CFG 批合并使有效批翻倍，显存约为双分支的两倍批激活，一步档在 CFG 下的实际上限约为无 CFG 时的一半，路由阈值需按是否启用 CFG 分别标定。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-53\">五十三 · 不适用的场景与硬边界</h3>\n<p>有三类场景一致性方案不适用，判断要硬。第一类是需要采样多样性的场景：一致性函数是确定性映射，同一先验噪声必得同一输出，若业务要求同一提示下多张差异明显的图，一步档必须靠噪声重采样或温度式扰动来补，而扰动会破坏轨迹自洽性，质量不可控；这类场景应直接用多步扩散而非一致性模型。第二类是条件极度复杂、细节密集的场景：一步档在复杂条件上细节不足是材料确认的局限，高分辨率叠加复杂条件时回退多步档的比例会上升，若回退比例高到使一步档的延迟优势被稀释，分档路由就失去意义，此时应重新评估是否值得部署一致性模型。第三类是训练分布外的条件：时间步网格与训练分布失配会导致多步采样质量下降，迁到新领域时若条件分布偏移大，网格需重标定，否则多步档的每一步都在分布外推理。</p>\n<p>硬边界还包括数值精度：推理侧用 FP8/NVFP4 降显存提吞吐时，一步档的质量验证不可省略，因为一步档没有多步迭代的误差平均效应，量化误差直接体现在输出上；多步档反而因重新加噪对量化误差有一定平滑。这与算子精度部分的结论一致，但迁移视角下的差别是：一步档的精度预算更紧，量化方案的选择应以一步档质量为约束，而非以多步档为约束反推。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-54\">五十四 · 迁移检查清单：把判断落成可执行项</h3>\n<p>迁到新模型或新领域时，按以下顺序检查，任一项不通过则不应把一步档作为主路径。其一，验证目标生成过程存在唯一终点的轨迹结构，离散扩散需确认转移核可定义相邻点对。其二，验证教师在目标域上的 ODE 轨迹自洽性，用两种步数跑到同一终点比较差异。其三，重标定时间步网格与 λ(t)，终点邻域加权，网格覆盖训练分布。其四，按单次前向激活峰值重算一步档批大小，CFG 启用时减半。其五，标定一步档与多步档的吞吐交点，据此设路由阈值并监控回退比例与超时率。其六，量化方案以一步档质量为验收约束。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>需改动</th><th>系统代价</th><th>不通过时的处置</th></tr></thead><tbody><tr><td>生成范式</td><td>连续→离散需换损失与状态表示</td><td>训练稳定性下降，λ(t) 敏感</td><td>只迁蒸馏压缩，不迁自洽训练</td></tr><tr><td>骨干</td><td>时间嵌入注入方式与门控初始化</td><td>多步档自洽性退化</td><td>放宽门控、终点邻域加权</td></tr><tr><td>分辨率</td><td>批大小按单次前向激活重算</td><td>一步档显存峰值卡上限</td><td>降批而非降分辨率</td></tr><tr><td>蒸馏</td><td>教师求解器精度与点对重建</td><td>点对生成成管线瓶颈</td><td>退回多步档或换高阶求解器</td></tr><tr><td>精度</td><td>量化后教师需重生成点对</td><td>一步档误差无平均效应</td><td>以一步档质量为验收约束</td></tr></tbody></table>\n<p>清单里最容易被跳过的是第二项与第五项：前者决定蒸馏出的学生是否可信，后者决定分档路由是否有经济意义。两项都依赖对目标域的实测而非类比，迁移判断的落点就在这里——不是问“一致性模型能不能用”，而是问“这条轨迹在这个域上是否自洽、这个交点是否落在业务负载的分布内”。</p>\n\n<h3 id=\"paper-consistency-models-2023-sec-55\">五十五 · 迁移边界：一致性蒸馏在哪些骨干、条件形态与规模上会失效</h3>\n<p>把一致性模型搬到新骨干上，第一件事不是改损失，而是核对时间步嵌入与轨迹终点定义是否仍然自洽。U-Net 与 DiT 的噪声预测参数化不同，一致性函数 f(x,t) 直接输出 x_ε，意味着学生网络必须继承教师的终点语义；若教师用 v-prediction 或 ε-prediction，蒸馏前要显式换算轨迹点对，否则相邻点对在数值上并不落在同一 ODE 轨迹，一致性损失约束的是错误目标。骨干容量也是硬边界：一步档把整条积分轨迹压缩进单次前向，等效感受野与非线性预算被大幅压缩，高分辨率、多物体、细粒度文本条件这三类负载最先退化。可用的工程判据是回退比例——若某类请求回退多步档的比例持续偏高，说明该条件形态已超出一致性函数的表达能力，而不是调度参数没调好。系统代价上，一步档省掉的是求解器循环的算力与显存驻留，但 VAE 解码与条件编码并不随之缩小，端到端延迟的下限被解码阶段锁死，因此迁移到更高分辨率时收益会被解码开销稀释。</p>\n<p>规模上限体现在两个方向。其一是蒸馏的教师精度：学生只能逼近教师 ODE 求解器给出的轨迹点对，教师求解器步数不足或离散化误差大时，学生继承的是有偏轨迹，多步一致性采样在细网格上会放大这一偏差，表现为网格越密质量反而下降。其二是批与显存的耦合：CFG 批合并使有效批翻倍，显存约为双分支的两倍批激活，一步档想靠增大批提吞吐，很快撞上中间激活与解码峰值。设一步档单请求前向代价为 <span class=\"formula\">$$C_{\\text{1step}}=C_{\\text{fwd}}(B)+C_{\\text{dec}}(B),\\quad B_{\\max}\\approx\\frac{M_{\\text{free}}-M_{\\text{dec}}}{a\\cdot s}$$</span> 其中 a 为每样本激活字节、s 为步数档位因子，可见多步档的 s 增大直接压低 B_max，按最大批统一调度必然在长请求上溢出。迁移到视频、3D 或长序列条件时，时间维或序列维使 a 成倍增长，一步档的批优势迅速消失，此时应把一致性模型定位为低延迟短请求通道，而非通用替代。</p>\n<p>不适用场景要明确列出：需要严格多模态对齐或精确数值条件的任务（如带物理约束的生成、可控编辑的迭代修正），一步映射缺少逐步校正环节，误差无法在采样过程中回收；依赖采样随机性做多样性的服务，一步档把轨迹坍缩为确定性映射，多样性需靠先验噪声与温度式扰动补回，这与一致性训练的自洽目标存在张力。蒸馏两阶段的数据流也不能混用：教师 ODE 轨迹点对只服务于蒸馏阶段，若误用于从头一致性训练，目标分布不一致会直接破坏稳定性。工程判断落在路由上——按条件复杂度与分辨率给出一致性档位的准入清单，监控每档步数、回退比例、显存峰值与解码耗时，把回退率当作模型能力边界的在线探针，而不是把它当异常吞掉。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 121\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Consistency Models</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"65.5\" x2=\"271.0\" y2=\"65.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 61.0 L 270.0 70.0 L 278.0 65.5 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"65.5\" x2=\"515.0\" y2=\"65.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 61.0 L 514.0 70.0 L 522.0 65.5 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"111.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2023 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Consistency Models 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出具体基线名称</td></tr><tr><td>主要结果</td><td>材料未给出可核验的 FID、采样步数与吞吐数字；论文卡层面只能确认方法支持…</td></tr><tr><td>消融</td><td>材料未给出消融实验数字；可推断的消融维度为时间步采样分布、损失权重 λ(t…</td></tr><tr><td>局限</td><td>材料未给出失败模式与消融的定量结果；可确认的局限包括一步生成在复杂条件上细…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-consistency-models-2023 · 共 9 个片段</p>\n";break;}}})();
